-- ============================================================================
-- LexiVance IELTS - Essential 5 Complete Seed Data
-- 15 Units & 301 Academic Vocabulary Words
-- ============================================================================

-- Insert Units
INSERT INTO vocabulary_units (unit_number, title, subtitle, description, display_order)
VALUES
  (1, 'Unit 1: The Foundations', 'Essential Words Book 5', 'Core academic verbs, adjectives, and descriptive concepts essential for IELTS Writing Task 2 and Speaking Band 7+.', 1),
  (2, 'Unit 2: Geography, Nature & Environment', 'Essential Words Book 5', 'Geographical, climatic, and natural environment vocabulary frequently encountered in IELTS Academic Reading.', 2),
  (3, 'Unit 3: Science, Logic & Intellect', 'Essential Words Book 5', 'Analytical, academic, and scientific terms essential for formal academic discourse and essay development.', 3),
  (4, 'Unit 4: Business, Economy & Governance', 'Essential Words Book 5', 'Commerce, administration, corporate infrastructure, and financial law vocabulary.', 4),
  (5, 'Unit 5: Medicine, Chemistry & Discovery', 'Essential Words Book 5', 'Pharmaceutical, clinical, and technological process terminology for IELTS Reading and Writing.', 5),
  (6, 'Unit 6: Physiology, Health & Challenges', 'Essential Words Book 5', 'Terms regarding anatomy, physical condition, overcoming medical hurdles, and exploration.', 6),
  (7, 'Unit 7: Biosphere & Marine Biology', 'Essential Words Book 5', 'Ecosystems, cellular biology, animal behavior, and organism survival vocabulary.', 7),
  (8, 'Unit 8: Culinary Arts, Health & Nutrition', 'Essential Words Book 5', 'Dietary science, agricultural yield, nutrition, and medical therapy terms.', 8),
  (9, 'Unit 9: History, Society & Heritage', 'Essential Words Book 5', 'Historical eras, architectural monuments, economic structures, and cultural heritage.', 9),
  (10, 'Unit 10: Commerce, Agriculture & Finance', 'Essential Words Book 5', 'Investment, agrarian technology, market mechanics, and resource management.', 10),
  (11, 'Unit 11: Arts, Human Behavior & Biography', 'Essential Words Book 5', 'Creative masterworks, psychological drives, and historical personal narratives.', 11),
  (12, 'Unit 12: Anthropology, Culture & Physique', 'Essential Words Book 5', 'Societal customs, physical aesthetics, professional ranks, and human heritage.', 12),
  (13, 'Unit 13: Community, Architecture & Wildlife', 'Essential Words Book 5', 'Urban infrastructure, biological kingdoms, considerate behavior, and protected sanctuaries.', 13),
  (14, 'Unit 14: Perception, Science & Innovation', 'Essential Words Book 5', 'Hypothesis testing, sensory science, academic skepticism, and historic renaissance innovations.', 14),
  (15, 'Unit 15: Logistics, Materials & Industry', 'Essential Words Book 5', 'Maritime trade, supply chain networks, material properties, and manufacturing dilemmas.', 15)
ON CONFLICT (unit_number) DO UPDATE SET
  title = EXCLUDED.title,
  subtitle = EXCLUDED.subtitle,
  description = EXCLUDED.description;

-- Insert 301 Vocabulary Words with Authentic Uzbek Translations
INSERT INTO vocabulary_words (
  word, normalized_word, unit_id, part_of_speech, ipa_us,
  definition_en, translation_uz, translation_ru,
  example_sentence_en, example_translation_uz,
  collocations, synonyms, display_order, is_published
)
SELECT
  w.word,
  LOWER(w.word),
  u.id,
  w.part_of_speech,
  w.ipa_us,
  w.definition_en,
  w.translation_uz,
  w.translation_ru,
  w.example_sentence_en,
  w.example_translation_uz,
  w.collocations,
  w.synonyms,
  w.display_order,
  TRUE
FROM (VALUES
  ('Allot', 1, 'verb', '/əˈlɒt/', 'To allot something means to give it to someone as their share or task.', 'Ajratmoq, bermoq', 'Выделять, распределять', 'The coach allotted each team five minutes to prepare a strategy.', 'Murabbiy har bir jamoaga strategiya tayyorlash uchun besh daqiqa ajratdi.', '["allot time","allot resources","allot tasks"]'::jsonb, '["allocate","assign","distribute","apportion"]'::jsonb, 1),
  ('Appall', 1, 'verb', '/əˈpɔːl/', 'To appall someone means to horrify, shock, or deeply disgust them.', 'Dahshatga solmoq, larzaga solmoq', 'Ужасать, потрясать', 'The boy was appalled when he saw the tragic consequences of the car accident.', 'Avtomobil halokatining fojiali oqibatlarini ko''rgan bola qattiq dahshatga tushdi.', '["be appalled by","appall the public","deeply appalled"]'::jsonb, '["horrify","shock","dismay","outrage"]'::jsonb, 2),
  ('Cache', 1, 'noun', '/kæʃ/', 'A cache is a hiding place, or a hidden collection of valuables, food, or weapons.', 'Maxfiy ombor, yashirin joy', 'Тайник, скрытый склад', 'The explorers discovered a secret cache of food left by the previous expedition.', 'Tadqiqotchilar oldingi ekspeditsiya qoldirgan maxfiy oziq-ovqat omborini topdilar.', '["hidden cache","weapons cache","secret cache"]'::jsonb, '["hoard","hiding place","store","stash"]'::jsonb, 3),
  ('Convenience', 1, 'noun', '/kənˈviː.ni.əns/', 'Convenience is the state of being able to proceed with something with little effort or difficulty.', 'Qulaylik, qulay fursat', 'Удобство, комфорт', 'Online shopping provides the ultimate convenience for busy working professionals.', 'Onlayn xaridlar band mutaxassislar uchun mislsiz qulaylik yaratadi.', '["at your convenience","modern convenience","for the sake of convenience"]'::jsonb, '["ease","comfort","handiness","suitability"]'::jsonb, 4),
  ('Dearth', 1, 'noun', '/dɜːθ/', 'A dearth is a scarcity or lack of something that is needed.', 'Yetishmovchilik, taqchillik', 'Нехватка, дефицит', 'There is an alarming dearth of qualified English teachers in remote rural schools.', 'Uzoq qishloq maktablarida malakali ingliz tili o''qituvchilarining xavotirli tanqisligi mavjud.', '["dearth of evidence","dearth of resources","acute dearth"]'::jsonb, '["scarcity","shortage","lack","deficiency"]'::jsonb, 5),
  ('Deliberate', 1, 'adjective', '/dɪˈlɪb.ər.ət/', 'Done intentionally, consciously, and on purpose rather than by accident.', 'Ataylab qilingan, qasddan', 'Преднамеренный, умышленный', 'His deliberate actions were aimed at undermining the authority of the manager.', 'Uning ataylab qilgan harakatlari menejerning obro''siga putur yetkazishga qaratilgan edi.', '["deliberate choice","deliberate attempt","deliberate lie"]'::jsonb, '["intentional","planned","premeditated","conscious"]'::jsonb, 6),
  ('Dire', 1, 'adjective', '/daɪər/', 'Extremely serious, urgent, or terrible in nature.', 'Dahshatli, o''ta jiddiy', 'Ужасный, бедственный, крайний', 'The economic crisis has plunged millions of families into dire poverty.', 'Iqtisodiy inqiroz millionlab oilalarni o''ta ayanchli qashshoqlikka duchor qildi.', '["in dire need","dire consequences","dire straits"]'::jsonb, '["dreadful","grave","critical","perilous"]'::jsonb, 7),
  ('Elapse', 1, 'verb', '/ɪˈlæps/', 'When time elapses, it passes by smoothly or unnoticed.', 'O''tmoq (vaqt haqida)', 'Проходить, истекать (о времени)', 'Several grueling months elapsed before the research findings were finally published.', 'Tadqiqot natijalari nihoyat e''lon qilinishidan oldin bir necha og''ir oylar o''tib ketdi.', '["time elapses","years elapse","before months elapse"]'::jsonb, '["pass","go by","slip away","expire"]'::jsonb, 8),
  ('Empathy', 1, 'noun', '/ˈem.pə.θi/', 'The ability to understand and share the feelings, emotions, and experiences of another.', 'Boshqalar dardini his qilish, hamdardlik', 'Сопереживание, эмпатия', 'A great leader must possess genuine empathy for the everyday struggles of their employees.', 'Buyuk yetakchi o''z xodimlarining kundalik qiyinchiliklariga nisbatan samimiy hamdardlikka ega bo''lishi kerak.', '["feel empathy","show empathy","lack of empathy"]'::jsonb, '["compassion","understanding","sensitivity","fellow feeling"]'::jsonb, 9),
  ('Fanciful', 1, 'adjective', '/ˈfæn.sɪ.fəl/', 'Unrealistic or coming from excessive imagination rather than reality.', 'Xayoliy, afsonaviy, asossiz', 'Причудливый, фантастический', 'His fanciful theories about time travel were quickly dismissed by serious scientists.', 'Uning vaqt sayohati haqidagi xayoliy nazariyalari jiddiy olimlar tomonidan darhol rad etildi.', '["fanciful notion","fanciful idea","fanciful tale"]'::jsonb, '["imaginative","whimsical","unrealistic","fictional"]'::jsonb, 10),
  ('Gripe', 1, 'verb', '/ɡraɪp/', 'To complain persistently or continuously about something trivial.', 'Nolimoq, arz qilmoq', 'Ворчать, жаловаться', 'The disgruntled workers began to gripe about the long working hours and low wages.', 'Norozi ishchilar uzoq ish soatlari va kam maoshdan tinimsiz noli boshladilar.', '["gripe about","common gripe","gripe constantly"]'::jsonb, '["complain","whine","grumble","protest"]'::jsonb, 11),
  ('Grueling', 1, 'adjective', '/ˈɡruː.ə.lɪŋ/', 'Extremely tiring, exhausting, and demanding great effort and endurance.', 'Mashaqqatli, holdan toydiradigan', 'Изнурительный, изматывающий', 'The athletes completed a grueling 42-kilometer marathon in the desert heat.', 'Sportchilar sahro jaziramasida mashaqqatli 42 kilometrlik marafonni yakunladilar.', '["grueling schedule","grueling workout","grueling journey"]'::jsonb, '["exhausting","punishing","arduous","taxing"]'::jsonb, 12),
  ('Mundane', 1, 'adjective', '/mʌnˈdeɪn/', 'Lacking interest or excitement; dull, ordinary, and routine.', 'Oddiy, zerikarli, kundalik', 'Обыденный, рутинный, скучный', 'She found cleaning the house to be a completely mundane and uninspiring chore.', 'U uyni tozalashni mutlaqo oddiy va zerikarli kundalik yumush deb bildi.', '["mundane task","mundane chores","mundane everyday life"]'::jsonb, '["ordinary","routine","commonplace","humdrum"]'::jsonb, 13),
  ('Opt', 1, 'verb', '/ɒpt/', 'To make a choice or decision from a range of available possibilities.', 'Tanlamoq, ma''qul ko''rmoq', 'Выбирать, предпочитать', 'Many high-achieving students opt to study abroad for better research opportunities.', 'Ko''plab a''lochi talabalar yaxshiroq ilmiy imkoniyatlar uchun chet elda o''qishni tanlaydilar.', '["opt for","opt to do something","opt out of"]'::jsonb, '["choose","select","elect","decide on"]'::jsonb, 14),
  ('Outrage', 1, 'noun', '/ˈaʊt.reɪdʒ/', 'An extremely strong reaction of anger, shock, or indignation.', 'Kuchli g''azab, norozilik', 'Возмущение, гнев, негодование', 'The corrupt politician''s light sentence caused widespread public outrage across the country.', 'Korrupsioner siyosatchiga yengil jazo berilishi butun mamlakat bo''ylab kuchli xalq g''azabiga sabab bo''ldi.', '["spark outrage","public outrage","express outrage"]'::jsonb, '["fury","indignation","anger","wrath"]'::jsonb, 15),
  ('Paltry', 1, 'adjective', '/ˈpɔːl.tri/', 'Very small, meager, or worthless in amount or importance.', 'Arzimagan, juda oz', 'Ничтожный, мизерный, жалкий', 'The intern was paid a paltry salary that could barely cover the cost of daily bus tickets.', 'Amaliyotchiga hatto kunlik avtobus chiptasini zo''rg''a qoplaydigan arzimagan maosh to''landi.', '["paltry sum","paltry amount","paltry wage"]'::jsonb, '["meager","trivial","insignificant","paltry sum"]'::jsonb, 16),
  ('Rectify', 1, 'verb', '/ˈrek.tɪ.faɪ/', 'To put right, correct, or remedy an error, problem, or mistake.', 'Tuzatmoq, to''g''rilamoq', 'Исправлять, устранять', 'The software engineering team worked tirelessly overnight to rectify the critical database bug.', 'Dasturchilar jamoasi ma''lumotlar bazasidagi jiddiy xatoni tuzatish uchun tun bo''yi tinimsiz ishladilar.', '["rectify a mistake","rectify an error","rectify the situation"]'::jsonb, '["correct","remedy","fix","resolve"]'::jsonb, 17),
  ('Resourceful', 1, 'adjective', '/rɪˈzɔːs.fəl/', 'Having the practical ability to find quick, clever ways to overcome difficulties.', 'Topqir, uddaburon', 'Находчивый, изобретательный', 'A resourceful detective can solve the most intricate mystery with minimal clues.', 'Topqir tergovchi eng murakkab jumboqni ham ozgina dalillar bilan yecha oladi.', '["resourceful person","resourceful mind","highly resourceful"]'::jsonb, '["inventive","ingenious","capable","clever"]'::jsonb, 18),
  ('Sustenance', 1, 'noun', '/ˈsʌs.tɪ.nəns/', 'Food and drink regarded as a source of strength, nutrition, and nourishment.', 'Ozuqa, tiriklik manbai', 'Пропитание, средства к существованию', 'Without proper sustenance and clean water, human beings cannot survive more than a few days.', 'To''g''ri ozuqa va toza suvsiz inson bir necha kundan ortiq yashay olmaydi.', '["daily sustenance","seek sustenance","sources of sustenance"]'::jsonb, '["nourishment","food","nutrition","livelihood"]'::jsonb, 19),
  ('Tedious', 1, 'adjective', '/ˈtiː.di.əs/', 'Too long, slow, or dull; tiresome and monotonous.', 'Zerikarli, toliqtiradigan', 'Утомительный, нудный, скучный', 'Manually entering thousands of rows of financial data into a spreadsheet is a tedious job.', 'Minglab moliyaviy ma''lumotlar qatorlarini jadvalga qo''lda kiritish juda zerikarli ishdir.', '["tedious task","tedious process","tedious routine"]'::jsonb, '["monotonous","boring","tiresome","wearisome"]'::jsonb, 20),
  ('Abbey', 2, 'noun', '/ˈæb.i/', 'A building or complex where monks or nuns live, work, and pray.', 'Abbatlik, monastir', 'Аббатство, монастырь', 'Westminster Abbey in London is renowned for royal weddings and historic coronations.', 'Londondagi Vestminster abbatligi qirollik to''ylari va tarixiy tojbosh kiyish marosimlari bilan mashhur.', '["ancient abbey","visit the abbey","abbey church"]'::jsonb, '["monastery","convent","priory","cloister"]'::jsonb, 21),
  ('Abundant', 2, 'adjective', '/əˈbʌn.dənt/', 'Existing or available in large quantities; plentiful and rich.', 'Mo''l-ko''l, serob', 'Обильный, изобильный', 'The valley is famous for its fertile soil and abundant fresh fruit harvests.', 'Vodiy o''zining unumdor tuprog''i va mo''l-ko''l yangi meva hosillari bilan mashhur.', '["abundant rainfall","abundant resources","abundant evidence"]'::jsonb, '["plentiful","copious","bountiful","ample"]'::jsonb, 22),
  ('Adjoin', 2, 'verb', '/əˈdʒɔɪn/', 'To be next to and joined with a building, room, or piece of land.', 'Tutashmoq, yondosh bo''lmoq', 'Примыкать, граничить', 'The luxurious master bedroom adjoins a spacious private marble bathroom.', 'Hashamatli asosiy yotoqxona keng xususiy marmar hammomga tutashgan.', '["adjoin the building","adjoin the garden","adjoining rooms"]'::jsonb, '["border","neighbor","abut","connect to"]'::jsonb, 23),
  ('Ample', 2, 'adjective', '/ˈæm.pəl/', 'Enough or more than enough; plentiful and generous in size or amount.', 'Yetarli, mo''l, keng', 'Достаточный, обильный, пространный', 'The students were given ample time to double-check their exam answers before submitting.', 'Talabalarga imtihon javoblarini topshirishdan oldin qayta tekshirib olish uchun yetarlicha vaqt berildi.', '["ample time","ample evidence","ample room"]'::jsonb, '["sufficient","adequate","plentiful","generous"]'::jsonb, 24),
  ('Arid', 2, 'adjective', '/ˈær.ɪd/', 'Having little or no rain; too dry or barren to support plentiful vegetation.', 'Qurg''oqchil, suvsiz', 'Засушливый, бесплодный', 'Cactus plants have evolved unique biological structures to survive in extremely arid deserts.', 'Kaktuslar o''ta qurg''oqchil sahrolarda yashab qolish uchun noyob biologik tuzilishga ega bo''lgan.', '["arid climate","arid land","arid zone"]'::jsonb, '["dry","barren","parched","desert-like"]'::jsonb, 25),
  ('Cathedral', 2, 'noun', '/kəˈθiː.drəl/', 'A very large, important church that is the headquarters of a bishop.', 'Bosh cherkov, sobor', 'Собор, кафедральный собор', 'Tourists were mesmerized by the stained-glass windows of the Gothic cathedral.', 'Sayyohlar Gotika uslubidagi bosh soborning vitraj oynalaridan lol qoldilar.', '["gothic cathedral","visit the cathedral","cathedral tower"]'::jsonb, '["basilica","minster","church","temple"]'::jsonb, 26),
  ('Deprive', 2, 'verb', '/dɪˈpraɪv/', 'To prevent someone from having or enjoying something essential.', 'Mahrum qilmoq', 'Лишать, отнимать', 'Prolonged insomnia can deprive the human brain of crucial restorative sleep.', 'Uzoq muddatli uyqusizlik inson miyasini hayotiy muhim oromdan mahrum qilishi mumkin.', '["deprive of rights","deprive of sleep","deprive of oxygen"]'::jsonb, '["strip","divest","rob","deny"]'::jsonb, 27),
  ('Drought', 2, 'noun', '/draʊt/', 'A prolonged period of abnormally low rainfall, leading to a shortage of water.', 'Qurg''oqchilik', 'Засуха', 'The severe drought destroyed thousands of hectares of crops and caused famine.', 'Qattiq qurg''oqchilik minglab gektar ekinlarni nobud qildi va ocharchilikka olib keldi.', '["severe drought","suffer from drought","drought conditions"]'::jsonb, '["dry spell","water shortage","aridity","lack of rain"]'::jsonb, 28),
  ('Eligible', 2, 'adjective', '/ˈel.ɪ.dʒə.bəl/', 'Having the right qualifications or meeting the necessary conditions to participate.', 'Munosib, talabga javob beradigan', 'Имеющий право, подходящий', 'Only university graduates with an IELTS band of 7.0 or higher are eligible for the scholarship.', 'Faqat IELTS bali 7.0 yoki undan yuqori bo''lgan oliygoh bitiruvchilari stipendiyaga munosib hisoblanadi.', '["eligible for a grant","eligible to vote","eligible candidate"]'::jsonb, '["qualified","entitled","suitable","fit"]'::jsonb, 29),
  ('Fast', 2, 'verb', '/fɑːst/', 'To abstain from all or certain kinds of food or drink, especially for religious or health reasons.', 'Ro''za tutmoq, parhez tutmoq', 'Поститься, воздерживаться от пищи', 'Millions of Muslims around the world fast from dawn to sunset during Ramadan.', 'Ramazon oyida dunyo bo''ylab millionlab musulmonlar tongdan quyosh botguncha ro''za tutadilar.', '["fast for health","intermittent fasting","religious fast"]'::jsonb, '["abstain","go hungry","diet","refrain from food"]'::jsonb, 30),
  ('Grumble', 2, 'verb', '/ˈɡrʌm.bəl/', 'To complain in a bad-tempered, quiet way; to murmur discontentedly.', 'To''ng''illamoq, noli-noli qilmoq', 'Ворчать, роптать, жаловаться', 'Commuters began to grumble when the morning commuter train was delayed by forty minutes.', 'Tonggi poyezd qirq daqiqaga kechikkanida yo''lovchilar to''ng''illab norozilik bildira boshladilar.', '["grumble about","grumble under one''s breath","stomach grumbles"]'::jsonb, '["mutter","grouse","whine","complain"]'::jsonb, 31),
  ('Inland', 2, 'adverb', '/ˌɪnˈlænd/', 'Situated in or moving toward the interior of a country away from the sea.', 'Ichkari hududda, dengizdan uzoqda', 'Вглубь страны, удаленный от моря', 'The coastal residents moved inland to find safety before the devastating hurricane arrived.', 'Qirg''oqbo''yi aholisi dahshatli to''fon kelishidan oldin xavfsizlik topish maqsadida ichkari hududga ko''chib o''tdi.', '["travel inland","inland sea","inland waterways"]'::jsonb, '["interior","upcountry","landward","central"]'::jsonb, 32),
  ('Moisture', 2, 'noun', '/ˈmɔɪs.tʃər/', 'Water or other liquid diffused in a small quantity as vapor, within a solid, or condensed on a surface.', 'Namlik, rutubat', 'Влажность, сырость, влага', 'Desert plants possess a thick waxy outer layer to prevent loss of vital moisture.', 'Sahro o''simliklari hayotiy namlikni yo''qotmaslik uchun qalin mumsimon qatlamga ega bo''ladi.', '["retain moisture","soil moisture","absorb moisture"]'::jsonb, '["dampness","wetness","humidity","condensation"]'::jsonb, 33),
  ('Nonetheless', 2, 'adverb', '/ˌnʌn.ðəˈles/', 'In spite of that; nevertheless.', 'Shunga qaramasdan, baribir', 'Тем не менее, все же, несмотря на это', 'The math exam was exceptionally challenging; nonetheless, Maria scored a perfect mark.', 'Matematika imtihoni nihoyatda qiyin edi; shunga qaramasdan, Mariya eng yuqori ballni oldi.', '["challenging, nonetheless","nonetheless important","successful nonetheless"]'::jsonb, '["nevertheless","even so","however","still"]'::jsonb, 34),
  ('Oath', 2, 'noun', '/əʊθ/', 'A solemn or formal promise, often calling upon God or a sacred object as a witness.', 'Qasam, ont, qasamyod', 'Клятва, присяга', 'The president placed his hand on the constitution and solemnly took the oath of office.', 'Prezident qo''lini konstitutsiyaga qo''yib, tantanali ravishda lavozim qasamyodini qabul qildi.', '["take an oath","under oath","break an oath"]'::jsonb, '["pledge","vow","promise","swear"]'::jsonb, 35),
  ('Prairie', 2, 'noun', '/ˈpreə.ri/', 'A large, open area of grassland, especially in North America.', 'Dasht, o''tloq yer, preriya', 'Прерия, степь', 'Vast herds of wild bison once roamed freely across the North American prairie.', 'Bir paytlar yovvoyi bizonlarning ulkan podalari Shimoliy Amerika dashtlarida erkin kezib yurgan.', '["vast prairie","prairie fire","prairie dogs"]'::jsonb, '["grassland","plain","steppe","savanna"]'::jsonb, 36),
  ('Ragged', 2, 'adjective', '/ˈræɡ.ɪd/', 'Old, torn, and in bad condition; wearing worn-out clothes.', 'Yirtiq-yamoq, juldur, titilgan', 'Оборванный, рваный, потрепанный', 'The poor orphan was shivering in the freezing winter wind in his ragged coat.', 'Kambag''al yetim bola o''zining juldur paltosida qahraton qish shamolida qaltirab turardi.', '["ragged clothes","ragged edge","ragged breath"]'::jsonb, '["tattered","torn","shabby","worn out"]'::jsonb, 37),
  ('Rugged', 2, 'adjective', '/ˈrʌɡ.ɪd/', 'Having a broken, rocky, and uneven surface; strong and tough.', 'G''adir-budur, qoyali, baquvvat', 'Неровный, скалистый, суровый', 'The hikers struggled to navigate through the rugged mountainous terrain.', 'Sayyohlar qoyali va g''adir-budur tog''li hududdan o''tishda qiynaldilar.', '["rugged terrain","rugged coastline","rugged landscape"]'::jsonb, '["rocky","rough","jagged","tough"]'::jsonb, 38),
  ('Scarce', 2, 'adjective', '/skeəs/', 'Insufficient for the demand; hard to find or rare.', 'Taqchil, kamyob', 'Дефицитный, скудный, редкий', 'Clean drinking water became increasingly scarce as the severe summer drought persisted.', 'Yozgi qattiq qurg''oqchilik davom etgani sari toza ichimlik suvi tobora taqchil bo''lib bordi.', '["scarce resources","make oneself scarce","food is scarce"]'::jsonb, '["rare","sparse","insufficient","in short supply"]'::jsonb, 39),
  ('Speculate', 2, 'verb', '/ˈspek.jə.leɪt/', 'To form a theory or conjecture about a subject without firm evidence.', 'Taxmin qilmoq, faraz qilmoq', 'Размышлять, строить предположения', 'Journalists began to speculate on who would be appointed as the next prime minister.', 'Jurnalistlar kim yangi bosh vazir etib tayinlanishi haqida turli taxminlar qila boshladilar.', '["speculate about","wildly speculate","speculate on the market"]'::jsonb, '["hypothesize","guess","conjecture","theorize"]'::jsonb, 40),
  ('Analytic', 3, 'adjective', '/ˌæn.əˈlɪt.ɪk/', 'Using or involving careful analysis and logical examination of complex parts.', 'Tahliliy, analitik', 'Аналитический', 'The IELTS Academic test requires strong analytic thinking skills to interpret visual charts.', 'IELTS Academic imtihoni vizual diagrammalarni tushunish uchun kuchli tahliliy fikrlashni talab qiladi.', '["analytic skills","analytic mind","analytic approach"]'::jsonb, '["analytical","logical","systematic","critical"]'::jsonb, 41),
  ('Assert', 3, 'verb', '/əˈsɜːt/', 'To state a fact or belief confidently, firmly, and forcefully.', 'Qat''iy ta''kidlamoq, tasdiqlamoq', 'Утверждать, заявлять', 'The scientist asserted that renewable green energy could power entire modern cities.', 'Olim qayta tiklanuvchi yashil energiya butun zamonaviy shaharlarni ta''minlay olishini qat''iy ta''kidladi.', '["assert authority","assert oneself","assert that"]'::jsonb, '["declare","maintain","state firmly","affirm"]'::jsonb, 42),
  ('Bachelor', 3, 'noun', '/ˈbætʃ.əl.ər/', 'An unmarried man; also a degree awarded by a university to an undergraduate student.', 'Bakalavr darajasi; bo''ydoq', 'Холостяк; бакалавр', 'After graduating with a Bachelor of Science, Farhod applied for an international master''s program.', 'Fanlar bo''yicha bakalavr darajasini tugatgach, Farhod xalqaro magistratura dasturiga hujjat topshirdi.', '["bachelor''s degree","eligible bachelor","bachelor of arts"]'::jsonb, '["single man","unmarried man","first degree"]'::jsonb, 43),
  ('Calculus', 3, 'noun', '/ˈkæl.kjə.ləs/', 'A branch of advanced mathematics that deals with rates of change and accumulation.', 'Matematik tahlil, oliy matematika', 'Дифференциальное и интегральное исчисление', 'Engineering students must master differential calculus to solve aerodynamics problems.', 'Muhandislik talabalari aerodinamika masalalarini yechish uchun differensial hisobni o''zlashtirishlari shart.', '["differential calculus","integral calculus","study calculus"]'::jsonb, '["advanced math","mathematical analysis","computation"]'::jsonb, 44),
  ('Celestial', 3, 'adjective', '/səˈles.tʃəl/', 'Relating to the sky or outer space as observed in astronomy; heavenly.', 'Samoviy, osmonga oid', 'Небесный, астрономический', 'Comets, stars, and distant planets are all fascinating celestial bodies.', 'Kometalar, yulduzlar va uzoq sayyoralarning barchasi maftunkor samoviy jismlardir.', '["celestial bodies","celestial navigation","celestial sphere"]'::jsonb, '["astronomical","heavenly","stellar","cosmic"]'::jsonb, 45),
  ('Cognitive', 3, 'adjective', '/ˈkɒɡ.nə.tɪv/', 'Connected with mental processes of understanding, learning, thinking, and memory.', 'Kognitiv, aqliy, bilishga oid', 'Когнитивный, познавательный', 'Learning a new foreign language enhances cognitive abilities and delays brain aging.', 'Yangi xorijiy tilni o''rganish kognitiv qobiliyatlarni oshiradi va miya qarishini sekinlashtiradi.', '["cognitive skills","cognitive development","cognitive decline"]'::jsonb, '["mental","intellectual","perceptual","cerebral"]'::jsonb, 46),
  ('Collision', 3, 'noun', '/kəˈlɪʒ.ən/', 'An instance of one moving object or vehicle striking violently against another.', 'To''qnashuv, to''qnashish', 'Столкновение, авария', 'The icy road conditions caused a major multiple-vehicle collision on the highway.', 'Muzlagan yo''l sharoiti trassada ko''plab transport vositalarining dahshatli to''qnashuviga sabab bo''ldi.', '["head-on collision","collision course","avoid a collision"]'::jsonb, '["crash","impact","accident","smash"]'::jsonb, 47),
  ('Competent', 3, 'adjective', '/ˈkɒm.pɪ.tənt/', 'Having the necessary ability, knowledge, or skill to do something successfully.', 'Malakali, layoqatli, yetuk', 'Компетентный, квалифицированный', 'Our company seeks a competent project manager who can deliver results on time.', 'Kompaniyamiz natijalarni o''z vaqtida taqdim eta oladigan malakali loyiha menejerini qidirmoqda.', '["highly competent","competent authority","competent professional"]'::jsonb, '["capable","skilled","qualified","proficient"]'::jsonb, 48),
  ('Diploma', 3, 'noun', '/dɪˈpləʊ.mə/', 'A certificate awarded by an educational establishment to show that someone has successfully completed a course of study.', 'Diplom, shahodatnoma', 'Диплом, свидетельство', 'Receiving her university diploma on stage was the proudest moment of Malika''s academic life.', 'Sahnada universitet diplomini qabul qilib olish Malikaning talabalik hayotidagi eng faxrli onlar edi.', '["high school diploma","receive a diploma","hold a diploma"]'::jsonb, '["degree","certificate","credential","qualification"]'::jsonb, 49),
  ('Excel', 3, 'verb', '/ɪkˈsel/', 'To be exceptionally good at or proficient in an activity or subject.', 'A''lo darajada uddalamoq, ustun kelmoq', 'Превосходить, отличаться, выделяться', 'Students who read academic literature regularly tend to excel in the IELTS Reading module.', 'Akademik adabiyotlarni muntazam o''qiydigan talabalar IELTS Reading modulida a''lo natijalar ko''rsatishga moyil bo''ladilar.', '["excel at something","excel in school","strive to excel"]'::jsonb, '["shine","surpass","stand out","distinguish oneself"]'::jsonb, 50),
  ('Geology', 3, 'noun', '/dʒiˈɒl.ə.dʒi/', 'The scientific study of the physical structure, history, and substances of the Earth.', 'Geologiya, yer tuzilishi fani', 'Геология', 'Geology provides vital insights into past climate changes, volcanic activity, and earthquakes.', 'Geologiya o''tmishdagi iqlim o''zgarishlari, vulqon faolligi va zilzilalar haqida muhim ma''lumotlar beradi.', '["study geology","geology of the region","field geology"]'::jsonb, '["earth science","geoscience","mineralogy"]'::jsonb, 51),
  ('Harness', 3, 'verb', '/ˈhɑː.nəs/', 'To control and make practical use of natural resources or power.', 'Jilovlamoq, kuchidan foydalanmoq', 'Обуздывать, использовать (энергию)', 'Engineers are striving to harness solar and wind energy to combat global climate change.', 'Muhandislar global iqlim o''zgarishiga qarshi kurashish uchun quyosh va shamol energiyasini jilovlashga intilmoqdalar.', '["harness energy","harness the power of","harness technology"]'::jsonb, '["utilize","exploit","channel","control"]'::jsonb, 52),
  ('Intellect', 3, 'noun', '/ˈɪn.təl.ekt/', 'The faculty of reasoning and understanding objectively, especially with regard to abstract matters.', 'Aql-zakovat, idrok', 'Интеллект, рассудок, ум', 'Albert Einstein was universally celebrated for his extraordinary creative intellect.', 'Albert Eynshteyn butun dunyoda o''zining g''ayritabiiy ijodiy aql-zakovati bilan e''tirof etilgan.', '["sharp intellect","towering intellect","appeal to the intellect"]'::jsonb, '["mind","brainpower","intelligence","wisdom"]'::jsonb, 53),
  ('Keen', 3, 'adjective', '/kiːn/', 'Having or showing eagerness or enthusiasm; highly developed senses.', 'O''tkir, ziyrak, ishtiyoqmand', 'Острый, проницательный, увлеченный', 'Dogs have an exceptionally keen sense of smell that allows them to track missing people.', 'Itlar yo''qolgan odamlarni qidirib topishga imkon beruvchi g''oyat o''tkir hid bilish qobiliyatiga ega.', '["keen interest","keen sense of smell","keen on doing something"]'::jsonb, '["sharp","eager","acute","enthusiastic"]'::jsonb, 54),
  ('Mythology', 3, 'noun', '/mɪˈθɒl.ə.dʒi/', 'A collection of myths or traditional stories, especially one belonging to a particular religious or cultural tradition.', 'Mifologiya, afsonashunoslik', 'Мифология', 'Greek mythology contains captivating epic tales of powerful gods, monsters, and brave heroes.', 'Yunon mifologiyasi qudratli xudolar, mahluqlar va jasur qahramonlar haqidagi maftunkor qissalarni o''z ichiga oladi.', '["greek mythology","nordic mythology","ancient mythology"]'::jsonb, '["folklore","legend","lore","mythos"]'::jsonb, 55),
  ('Physiology', 3, 'noun', '/ˌfɪz.iˈɒl.ə.dʒi/', 'The scientific branch of biology that deals with the normal functions of living organisms and their parts.', 'Fiziologiya, organizm faoliyati fani', 'Физиология', 'Understanding human physiology helps doctors diagnose illnesses and recommend proper treatments.', 'Inson fiziologiyasini tushunish shifokorlarga kasalliklarni aniqlash va to''g''ri davolash choralarini belgilashda yordam beradi.', '["human physiology","plant physiology","exercise physiology"]'::jsonb, '["biological functioning","anatomy","body processes"]'::jsonb, 56),
  ('Radioactive', 3, 'adjective', '/ˌreɪ.di.əʊˈæk.tɪv/', 'Emitting radiation through the spontaneous disintegration of atomic nuclei.', 'Radioaktiv, nurlanuvchi', 'Радиоактивный', 'Special protective lead suits are necessary when handling hazardous radioactive waste.', 'Xavfli radioaktiv chiqindilar bilan ishlaganda maxsus qo''rg''oshinli himoya kostyumlari talab etiladi.', '["radioactive waste","radioactive decay","radioactive material"]'::jsonb, '["radiating","atomic","nuclear","irradiated"]'::jsonb, 57),
  ('Relativity', 3, 'noun', '/ˌrel.əˈtɪv.ə.ti/', 'The dependence of physical phenomena on relative motion; Einstein''s theory of space, time, and gravity.', 'Nisbiylik nazariyasi, nisbiylik', 'Относительность, теория относительности', 'Einstein''s theory of general relativity fundamentally transformed our understanding of the universe.', 'Eynshteynning umumiy nisbiylik nazariyasi koinot haqidagi tasavvurlarimizni tubdan o''zgartirdi.', '["theory of relativity","general relativity","special relativity"]'::jsonb, '["relative nature","Einstein''s theory","comparativeness"]'::jsonb, 58),
  ('Sociology', 3, 'noun', '/ˌsəʊ.siˈɒl.ə.dʒi/', 'The study of the development, structure, and functioning of human society.', 'Sotsiologiya, jamiyatshunoslik', 'Социология', 'Sociology analyzes how modern social media platforms influence adolescent behavior.', 'Sotsiologiya zamonaviy ijtimoiy tarmoqlar o''smirlar xulq-atvoriga qanday ta''sir qilishini tahlil qiladi.', '["study sociology","professor of sociology","sociology department"]'::jsonb, '["social science","study of society","demographics"]'::jsonb, 59),
  ('Theoretical', 3, 'adjective', '/ˌθɪəˈret.ɪ.kəl/', 'Concerned with or involving the theory of a subject or area of study rather than its practical application.', 'Nazariy, ilmiy-nazariy', 'Теоретический', 'Before conducting laboratory tests, physicists formulated a complex theoretical model.', 'Laboratoriya sinovlarini o''tkazishdan oldin fiziklar murakkab nazariy model tuzib chiqdilar.', '["theoretical framework","theoretical knowledge","purely theoretical"]'::jsonb, '["hypothetical","abstract","conceptual","speculative"]'::jsonb, 60),
  ('Concur', 3, 'verb', '/kənˈkɜːr/', 'To be of the same opinion; to agree with another person or viewpoint.', 'Fikrga qo''shilmoq, hamfikr bo''lmoq', 'Соглашаться, сходиться во мнениях', 'All medical specialists concurred that immediate surgical intervention was necessary.', 'Barcha tibbiyot mutaxassislari zudlik bilan jarrohlik aralashuvi zarurligiga bir ovozdan qo''shildilar.', '["concur with","strongly concur","concur in the decision"]'::jsonb, '["agree","coincide","concord","be in accord"]'::jsonb, 61),
  ('Administrator', 4, 'noun', '/ədˈmɪn.ɪ.streɪ.tər/', 'A person responsible for running a business, organization, or school system.', 'Ma''mur, boshqaruvchi', 'Администратор, управляющий', 'The university administrator introduced a more efficient online course enrollment system.', 'Universitet ma''muri kurslarga onlayn yozilishning yanada samarali tizimini joriy qildi.', '["hospital administrator","system administrator","school administrator"]'::jsonb, '["manager","director","executive","coordinator"]'::jsonb, 62),
  ('Affluent', 4, 'adjective', '/ˈæf.lu.ənt/', 'Having a great deal of money; wealthy and prosperous.', 'Badavlat, boy, farovon', 'Богатый, зажиточный, состоятельный', 'Families in affluent neighborhoods typically have access to superior educational facilities.', 'Boy tumanlardagi oilalar odatda yuqori sifatli ta''lim muassasalaridan foydalanish imkoniyatiga ega.', '["affluent society","affluent suburb","affluent families"]'::jsonb, '["wealthy","rich","prosperous","opulent"]'::jsonb, 63),
  ('Audit', 4, 'noun', '/ˈɔː.dɪt/', 'An official inspection of an individual''s or organization''s accounts, typically by an independent body.', 'Audit, moliyaviy taftish', 'Аудит, ревизия, проверка', 'The independent financial audit revealed several discrepancies in company tax filings.', 'Mustaqil moliyaviy audit kompaniyaning soliq hisobotlarida bir qancha tafovutlarni aniqladi.', '["conduct an audit","tax audit","annual audit"]'::jsonb, '["inspection","examination","review","scrutiny"]'::jsonb, 64),
  ('Automate', 4, 'verb', '/ˈɔː.tə.meɪt/', 'To convert a process or facility to largely automatic or robotic operation.', 'Avtomatlashtirmoq', 'Автоматизировать', 'Car manufacturing factories automate heavy assembly lines using robotic arms.', 'Avtomobil zavodlari robot qo''llardan foydalanib, og''ir yig''ish liniyalarini avtomatlashtiradi.', '["automate processes","fully automated","automate tasks"]'::jsonb, '["mechanize","computerize","robotize","streamline"]'::jsonb, 65),
  ('Bribe', 4, 'verb', '/braɪb/', 'To dishonestly persuade someone to act in one''s favor by giving them money or a gift.', 'Pora bermoq, sotib olmoq', 'Давать взятку, подкупать', 'The dishonest contractor attempted to bribe the city building inspector to overlook safety violations.', 'Noinsof pudratchi xavfsizlik qoidabuzarliklariga ko''z yumish uchun shahar bino inspektoriga pora berishga urindi.', '["accept a bribe","attempt to bribe","bribe an official"]'::jsonb, '["pay off","suborn","corrupt","grease someone''s palm"]'::jsonb, 66),
  ('Corrupt', 4, 'adjective', '/kəˈrʌpt/', 'Having or showing a willingness to act dishonestly in return for money or personal gain.', 'Korrupsiyalashgan, poraxo''r', 'Коррумпированный, продажный', 'The citizens demanded the resignation of the corrupt mayor after the bribery scandal was exposed.', 'Pora mojarosi fosh etilgach, fuqarolar korrupsiyalashgan shahar merining iste''fosini talab qildilar.', '["corrupt politicians","corrupt practices","fight corrupt officials"]'::jsonb, '["dishonest","fraudulent","crooked","unethical"]'::jsonb, 67),
  ('Dispose', 4, 'verb', '/dɪˈspəʊz/', 'To get rid of something that is no longer needed or useful (usually ''dispose of'').', 'Bartaraf etmoq, tashlab yubormoq', 'Избавляться, ликвидировать', 'Hospitals must carefully dispose of hazardous medical waste to protect the environment.', 'Shifoxonalar atrof-muhitni asrash uchun xavfli tibbiy chiqindilarni ehtiyotkorlik bilan bartaraf etishlari shart.', '["dispose of waste","properly dispose of","dispose of assets"]'::jsonb, '["throw away","discard","get rid of","eliminate"]'::jsonb, 68),
  ('Headquarters', 4, 'noun', '/ˌhedˈkwɔː.təz/', 'The main office or administrative center of an enterprise or military organization.', 'Bosh qarorgoh, markaziy idora', 'Штаб-квартира, главный офис', 'Tech giant Google relocated its European regional headquarters to a modern tech hub in Dublin.', 'Google texnologiya giganti o''zining Yevropa mintaqaviy bosh qarorgohini Dublindagi zamonaviy xabga ko''chirdi.', '["company headquarters","set up headquarters","at the headquarters"]'::jsonb, '["main office","base","command center","head office"]'::jsonb, 69),
  ('Incentive', 4, 'noun', '/ɪnˈsen.tɪv/', 'A thing that motivates, encourages, or drives someone to do something.', 'Rag''bat, rag''batlantiruvchi omil', 'Стимул, поощрение, мотивация', 'The management offered financial bonus incentives to boost workers'' monthly productivity.', 'Rahbariyat xodimlarning oylik mehnat unumdorligini oshirish uchun moliyaviy bonus rag''batlarini taklif qildi.', '["financial incentive","strong incentive","tax incentive"]'::jsonb, '["motivation","stimulus","encouragement","inducement"]'::jsonb, 70),
  ('Infrastructure', 4, 'noun', '/ˈɪn.frəˌstrʌk.tʃər/', 'The basic physical and organizational structures and facilities needed for the operation of a society or enterprise.', 'Infratuzilma', 'Инфраструктура', 'Heavy investments in transport infrastructure and high-speed rail accelerate economic growth.', 'Transport infratuzilmasi va tezyurar temir yo''llarga kiritilgan katta investitsiyalar iqtisodiy o''sishni tezlashtiradi.', '["transport infrastructure","critical infrastructure","digital infrastructure"]'::jsonb, '["framework","foundation","utilities","facilities"]'::jsonb, 71),
  ('Legislate', 4, 'verb', '/ˈledʒ.ɪ.sleɪt/', 'To make or enact laws through a legislative body.', 'Qonun chiqarmoq, qonun qabul qilmoq', 'Издавать законы, законодательствовать', 'Parliament convened an emergency session to legislate strict limits on carbon emissions.', 'Parlament uglerod chiqindilariga qat''iy cheklovlar qo''yish to''g''risida qonun chiqarish uchun favqulodda sessiya chaqirdi.', '["legislate against","power to legislate","legislate for change"]'::jsonb, '["enact laws","pass laws","ordain","prescribe"]'::jsonb, 72),
  ('Legitimate', 4, 'adjective', '/ləˈdʒɪt.ə.mət/', 'Conforming to the law or to rules; justifiable and valid.', 'Qonuniy, asosli, haqqoniy', 'Законный, легитимный, обоснованный', 'The customer had a completely legitimate complaint regarding the defective electronic goods.', 'Xaridorda nuqsonli elektron tovarlar bo''yicha to''liq asosli va haqqoniy shikoyat bor edi.', '["legitimate business","legitimate concern","legitimate right"]'::jsonb, '["lawful","legal","valid","justifiable"]'::jsonb, 73),
  ('Manipulate', 4, 'verb', '/məˈnɪp.jə.leɪt/', 'To control or influence a person, situation, or data cleverly or unscrupulously.', 'O''z manfaatiga moslab boshqarmoq, manipulyatsiya qilmoq', 'Манипулировать, подтасовывать', 'Unethical advertisers often try to manipulate consumer emotions to boost impulse buying.', 'Noinsof reklama beruvchilar his-tuyg''ularni manipulyatsiya qilib, odamlarni keraksiz xaridlarga undashga urinadilar.', '["manipulate public opinion","manipulate data","manipulate people"]'::jsonb, '["exploit","influence","maneuver","rig"]'::jsonb, 74),
  ('Merchandise', 4, 'noun', '/ˈmɜː.tʃən.daɪs/', 'Goods to be bought and sold in commerce.', 'Mollar, tovarlar, mahsulot', 'Товары, мерчандайз', 'The department store arranged its seasonal merchandise attractively in the front display windows.', 'Universam o''zining mavsumiy tovarlarini old vitrinalarda juda chiroyli qilib terib qo''ydi.', '["official merchandise","display merchandise","retail merchandise"]'::jsonb, '["goods","commodities","products","wares"]'::jsonb, 75),
  ('Retail', 4, 'noun', '/ˈriː.teɪl/', 'The sale of goods to the general public in relatively small quantities for immediate use or consumption.', 'Chakana savdo', 'Розничная торговля, розница', 'The rise of e-commerce has severely disrupted the traditional brick-and-mortar retail sector.', 'Elektron tijoratning rivojlanishi an''anaviy chakana savdo do''konlari faoliyatiga jiddiy zarba berdi.', '["retail price","retail outlet","retail industry"]'::jsonb, '["shopkeeping","direct selling","retail trade"]'::jsonb, 76),
  ('Revenue', 4, 'noun', '/ˈrev.ən.juː/', 'Income, especially when of a company or organization and of a substantial nature.', 'Daromad, umumiy tushum', 'Доход, выручка, поступления', 'Higher international tourist visits generated substantial tax revenue for the municipal government.', 'Xalqaro sayyohlar oqimining ko''payishi shahar hokimiyati uchun katta soliq tushumlarini keltirdi.', '["generate revenue","annual revenue","tax revenue"]'::jsonb, '["income","earnings","receipts","proceeds"]'::jsonb, 77),
  ('Rubbish', 4, 'noun', '/ˈrʌb.ɪʃ/', 'Waste material; things that are no longer useful and are discarded as garbage; also worthless ideas.', 'Axlat, chiqindi, keraksiz narsalar', 'Мусор, отходы, ерунда', 'The floor around the garbage can was covered with all kinds of discarded rubbish.', 'Chiqindi qutisi atrofidagi pol har xil tashlab ketilgan axlatlar bilan qoplangan edi.', '["pile of rubbish","clear the rubbish","talk rubbish"]'::jsonb, '["garbage","trash","waste","litter","debris"]'::jsonb, 78),
  ('Subsidy', 4, 'noun', '/ˈsʌb.sɪ.di/', 'A sum of money granted by the government to assist an industry or business so that the price of a commodity or service may remain low.', 'Subsidiya, moliyaviy yordam', 'Субсидия, дотация', 'Farmers received a state subsidy to help cover the surging costs of specialized fertilizers.', 'Fermerlar maxsus o''g''itlarning oshib ketgan xarajatlarini qoplash uchun davlat subsidiyasini oldilar.', '["government subsidy","agricultural subsidy","qualify for a subsidy"]'::jsonb, '["grant","aid","allowance","financial support"]'::jsonb, 79),
  ('Transaction', 4, 'noun', '/trænˈzæk.ʃən/', 'An instance of buying or selling something; a completed business deal.', 'Moliyaviy bitim, operatsiya', 'Сделка, транзакция, операция', 'Banking apps send instant phone alerts whenever an unauthorized debit card transaction occurs.', 'Bank ilovalari ruxsatsiz karta operatsiyasi sodir bo''lganda darhol telefonga xabarnoma yuboradi.', '["financial transaction","secure transaction","complete a transaction"]'::jsonb, '["deal","business deal","exchange","bargain"]'::jsonb, 80),
  ('Violate', 4, 'verb', '/ˈvaɪ.ə.leɪt/', 'To break, infringe, or act in disregard of a law, rule, or agreement.', 'Buzmoq (qonun yoki qoidani), poymol qilmoq', 'Нарушать (закон, правила), попирать', 'Driving through a red light directly violates fundamental traffic safety regulations.', 'Qizil chiroqda harakatlanish asosiy yo''l harakati xavfsizligi qoidalarini to''g''ridan-to''g''ri buzadi.', '["violate human rights","violate the law","violate terms of service"]'::jsonb, '["break","breach","infringe","disobey"]'::jsonb, 81),
  ('Assess', 5, 'verb', '/əˈses/', 'To evaluate or estimate the nature, quality, ability, or significance of someone or something.', 'Baholamoq, darajasini aniqlamoq', 'Оценивать', 'IELTS examiners assess test takers based on fluency, lexical resource, grammar, and pronunciation.', 'IELTS imtihon oluvchilari nomzodlarni ravonlik, so''z boyligi, grammatika va talaffuz bo''yicha baholaydilar.', '["assess damage","assess performance","carefully assess"]'::jsonb, '["evaluate","judge","appraise","rate"]'::jsonb, 82),
  ('Astonish', 5, 'verb', '/əˈstɒn.ɪʃ/', 'To surprise or impress someone greatly; to amaze.', 'Hayratda qoldirmoq, lol qoldirmoq', 'Удивлять, изумлять', 'The young pianist astonished the entire audience with her flawless classical performance.', 'Yosh pianinochi o''zining benuqson klassik ijrosi bilan butun tomoshabinlarni lol qoldirdi.', '["astonish the world","never ceases to astonish","be astonished by"]'::jsonb, '["amaze","stun","astound","surprise"]'::jsonb, 83),
  ('Commence', 5, 'verb', '/kəˈmens/', 'To begin or start an event or action.', 'Boshlamoq, boshlanmoq', 'Начинать, начинаться', 'The university graduation ceremony will commence promptly at ten o''clock tomorrow morning.', 'Universitet bitiruv marosimi ertaga ertalab soat roppa-rosa o''nda boshlanadi.', '["commence operations","commence proceedings","commence work"]'::jsonb, '["begin","start","initiate","embark on"]'::jsonb, 84),
  ('Essence', 5, 'noun', '/ˈes.əns/', 'The intrinsic nature or indispensable quality of something that determines its character.', 'Mohiyat, mag''iz, asos', 'Сущность, суть', 'Mutual trust, honesty, and communication form the true essence of a lasting friendship.', 'O''zaro ishonch, halollik va muloqot mustahkam do''stlikning asl mohiyatini tashkil etadi.', '["in essence","time is of the essence","capture the essence"]'::jsonb, '["core","heart","substance","nature"]'::jsonb, 85),
  ('Extract', 5, 'verb', '/ɪkˈstrækt/', 'To remove or take out, especially by effort or force; to deduce or pull from a source.', 'Ajratib olmoq, sug''urib olmoq', 'Извлекать, добывать, выжимать', 'Scientists extract essential healing oils from medicinal plants to create soothing herbal ointments.', 'Olimlar shifobaxsh dorivor moylarni o''simliklardan ajratib olib, davolovchi mazlar tayyorlaydilar.', '["extract teeth","extract information","extract minerals"]'::jsonb, '["withdraw","pull out","derive","obtain"]'::jsonb, 86),
  ('Fabulous', 5, 'adjective', '/ˈfæb.jə.ləs/', 'Extraordinary, wonderful, or almost impossible to believe.', 'Ajoyib, zo''r, ertaknamo', 'Сказочный, потрясающий, великолепный', 'The mountain summit offered a fabulous panoramic view of the snow-covered valleys below.', 'Tog'' cho''qqisidan pastdagi qor bilan qoplangan vodiylarning ajoyib manzarasi ochildi.', '["fabulous view","fabulous news","look fabulous"]'::jsonb, '["magnificent","marvelous","splendid","superb"]'::jsonb, 87),
  ('Haste', 5, 'noun', '/heɪst/', 'Excessive speed or urgency of movement or action; hurry.', 'Shoshqaloqlik, shoshilish', 'Спешка, торопливость', 'In his haste to catch the early flight, Jasur forgot his international passport at home.', 'Erta tonggi samolyotga ulgurish uchun shoshqaloqlik qilgan Jasur xorijiy pasportini uyda unutib qoldirdi.', '["in haste","make haste","more haste, less speed"]'::jsonb, '["hurry","rush","swiftness","speed"]'::jsonb, 88),
  ('Impulse', 5, 'noun', '/ˈɪm.pʌls/', 'A sudden strong and unreflective urge or desire to act.', 'Turtki, qiziqqonlik, ichki intilish', 'Импульс, порыв, побуждение', 'She resisted the sudden impulse to buy an expensive designer handbag that was on sale.', 'U sotuvga qo''yilgan qimmatbaho brend sumkasini to''satdan sotib olish turtkisiga qarshi turdi.', '["on impulse","resist the impulse","sudden impulse"]'::jsonb, '["urge","instinct","whim","drive"]'::jsonb, 89),
