  ('Synthetic', 5, 'adjective', '/sɪnˈθet.ɪk/', 'Made by chemical synthesis, especially to imitate a natural product.', 'Sintetik, sun''iy', 'Синтетический, искусственный', 'Synthetic athletic fabrics are engineered to wick away sweat and dry quickly during workouts.', 'Sintetik sport matolari terni tez shimib, mashg''ulot paytida tez qurish uchun ishlab chiqilgan.', '["synthetic materials","synthetic fibers","synthetic chemicals"]'::jsonb, '["artificial","man-made","manufactured","simulated"]'::jsonb, 100),
