  ('Nucleus', 7, 'noun', '/ˈnjuː.kli.əs/', 'The central and most important part of an object, movement, or group; the core of an atom or cell.', 'Yadro, markaziy asos', 'Ядро, центр', 'The cell''s genetic material and DNA instructions are securely housed inside its nucleus.', 'Hujayraning genetik materiali va DNK ko''rsatmalari uning yadrosi ichida xavfsiz saqlanadi.', '["atomic nucleus","cell nucleus","form the nucleus of"]'::jsonb, '["core","center","heart","hub"]'::jsonb, 133),
  ('Parasite', 7, 'noun', '/ˈpær.ə.saɪt/', 'An organism that lives in or on an organism of another species and benefits by deriving nutrients at the other''s expense.', 'Parazit, tekinxo''r organizm', 'Паразит, дармоед', 'Fleas and ticks are harmful parasites that feed on the blood of mammals.', 'Burgalar va kanalar sutemizuvchilar qoni bilan oziqlanadigan zararli parazitlardir.', '["intestinal parasite","host and parasite","parasite infection"]'::jsonb, '["bloodsucker","leech","hanger-on"]'::jsonb, 134),
  ('Prominent', 7, 'adjective', '/ˈprɒm.ɪ.nənt/', 'Important; famous; or situated so as to catch the attention readily.', 'Taniqli, ko''zga ko''ringan, mashhur', 'Выдающийся, заметный, видный', 'Professor Karimov played a prominent role in modernizing the nation''s medical education.', 'Professor Karimov mamlakat tibbiy ta''limini modernizatsiya qilishda ko''zga ko''ringan rol o''ynadi.', '["prominent figure","prominent position","play a prominent role"]'::jsonb, '["distinguished","notable","eminent","conspicuous"]'::jsonb, 135),
  ('Repetitive', 7, 'adjective', '/rɪˈpet.ə.tɪv/', 'Containing or characterized by repetition, especially when this is considered boring or tedious.', 'Takroriy, bir xil, zerikarli', 'Повторяющийся, однообразный', 'Factory automation eliminates the need for workers to perform dangerous and repetitive manual tasks.', 'Zavodlarni avtomatlashtirish ishchilarning xavfli va takroriy qo''l mehnatini bajarish zaruratini yo''qotadi.', '["repetitive strain","repetitive task","repetitive motions"]'::jsonb, '["monotonous","tedious","recurrent","unvaried"]'::jsonb, 136),
  ('Reproductive', 7, 'adjective', '/ˌriː.prəˈdʌk.tɪv/', 'Relating to the biological process of producing offspring.', 'Reproduktiv, ko''payishga oid', 'Репродуктивный', 'Scientists studied the migratory patterns and reproductive habits of North Atlantic whales.', 'Olimlar Shimoliy Atlantika kitlarining ko''chish yo''llari va ko''payish odatlarini o''rgandilar.', '["reproductive system","reproductive health","reproductive cycle"]'::jsonb, '["generative","propagative","procreative"]'::jsonb, 137),
  ('Temperate', 7, 'adjective', '/ˈtem.pər.ət/', 'Relating to or denoting a region or climate characterized by mild temperatures.', 'Mo''''tadil, yoqimli (iqlim)', 'Умеренный (о климате)', 'Apples, cherries, and pears flourish best in temperate climates with well-defined seasons.', 'Olma, gilos va nok to''rtta fasli aniq bo''lgan mo''''tadil iqlimlarda eng yaxshi hosil beradi.', '["temperate climate","temperate zone","temperate forest"]'::jsonb, '["mild","moderate","clement","pleasant"]'::jsonb, 138),
  ('Tolerance', 7, 'noun', '/ˈtɒl.ər.əns/', 'The ability or willingness to tolerate the existence of opinions or behavior that one does not necessarily agree with; also capacity to endure hardships.', 'Bag''rikenglik, chidamlilik, bardosh', 'Толерантность, терпимость, выносливость', 'Religious tolerance and cultural respect are fundamental cornerstones of a civilized society.', 'Diniy bag''rikenglik va madaniy hurmat madaniyatli jamiyatning asosiy poydevoridir.', '["religious tolerance","high tolerance for pain","zero tolerance"]'::jsonb, '["acceptance","forbearance","open-mindedness","patience"]'::jsonb, 139),
  ('Undergo', 7, 'verb', '/ˌʌn.dəˈɡəʊ/', 'To experience or be subjected to something, typically a process that is unpleasant or arduous.', 'Boshdan kechirmoq, o''tmoq (operatsiya, sinov)', 'Подвергаться, претерпевать, проходить', 'The athlete had to undergo intensive knee surgery followed by six months of physical therapy.', 'Sportchi tizzasini og''ir jarrohlikdan o''tkazishi va undan so''ng olti oylik fizioterapiyani boshdan kechirishi kerak edi.', '["undergo surgery","undergo training","undergo tests"]'::jsonb, '["experience","endure","go through","submit to"]'::jsonb, 140),
  ('Vulnerable', 7, 'adjective', '/ˈvʌl.nər.ə.bəl/', 'Susceptible to physical or emotional attack or harm; easily hurt.', 'Zaif, himoyasiz, ojiz', 'Уязвимый, ранимый, беззащитный', 'Infants and the elderly are especially vulnerable to seasonal respiratory infections during winter.', 'Qish mavsumida go''daklar va qariyalar mavsumiy nafas yo''llari infeksiyalariga nisbatan ayniqsa zaif bo''ladilar.', '["vulnerable position","vulnerable population","feel vulnerable"]'::jsonb, '["defenseless","susceptible","exposed","fragile"]'::jsonb, 141),
  ('Adept', 8, 'adjective', '/əˈdept/', 'Very skilled or proficient at something.', 'Epchil, mohir, usta', 'Искусный, знающий, эксперт', 'She became adept at resolving complex customer disputes calmly and diplomatically.', 'U mijozlar o''rtasidagi murakkab nizolarni bosiqlik va diplomatiya bilan hal qilishda mohir bo''lib yetishdi.', '["adept at handling","adept in negotiations","highly adept"]'::jsonb, '["expert","proficient","skillful","talented"]'::jsonb, 142),
  ('Barren', 8, 'adjective', '/ˈbær.ən/', 'Land too poor to produce much or any vegetation; bleak and lifeless.', 'Unumsiz, qaqragan, hosilsiz', 'Бесплодный, пустой, бесплодная земля', 'The volcanic eruption turned the lush green farmland into a desolate, barren wasteland.', 'Vulqon otilishi yam-yashil unumdor dehqonchilik yerlarini kimsasiz, unumsiz biyobonga aylantirdi.', '["barren landscape","barren land","barren soil"]'::jsonb, '["infertile","unproductive","sterile","desolate"]'::jsonb, 143),
  ('Ceramic', 8, 'adjective', '/səˈræm.ɪk/', 'Made of clay and hardened by heat, or relating to pottery.', 'Sopol, keramik', 'Керамический', 'Samarkand is globally famed for its majestic mosques adorned with turquoise ceramic tiles.', 'Samarqand feruza rangli sopol koshinlar bilan bezatilgan muhtasham masjidlari bilan dunyoga mashhur.', '["ceramic tiles","ceramic vase","ceramic art"]'::jsonb, '["pottery","porcelain","earthenware","clay"]'::jsonb, 144),
  ('Culinary', 8, 'adjective', '/ˈkʌl.ɪ.nər.i/', 'Of or for cooking; relating to kitchens and gastronomy.', 'Pazandalik, oshpazlikka oid', 'Кулинарный', 'Tashkent offers an extraordinary culinary experience renowned for flavorful plov and samsa.', 'Toshkent mazali osh va somsasi bilan tanilgan ajoyib pazandalik tajribasini taqdim etadi.', '["culinary skills","culinary arts","culinary tradition"]'::jsonb, '["gastronomic","cooking","epicurean"]'::jsonb, 145),
  ('Dense', 8, 'adjective', '/dens/', 'Closely compacted in substance; having parts crowded closely together.', 'Zich, qalin, quyuq', 'Плотный, густой', 'The mountain hikers got lost in the dense, impenetrable fog that rolled in at dusk.', 'Tog'' sayyohlari shom paytida tushgan quyuq va qalin tumanda adashib qoldilar.', '["dense forest","dense fog","dense population"]'::jsonb, '["thick","compact","crowded","tight"]'::jsonb, 146),
  ('Dignity', 8, 'noun', '/ˈdɪɡ.nə.ti/', 'The state or quality of being worthy of honor or respect; self-respect.', 'Qadr-qimmat, sha''n, viqor', 'Достоинство, благородство', 'Even in the face of bitter defeat, the champion maintained his poise, grace, and dignity.', 'Hatto achchiq mag''lubiyat oldida ham chempion o''zining viqori, bosiqligi va qadr-qimmatini saqlab qoldi.', '["human dignity","with dignity","loss of dignity"]'::jsonb, '["self-respect","pride","nobility","honor"]'::jsonb, 147),
  ('Dominate', 8, 'verb', '/ˈdɒm.ɪ.neɪt/', 'To have a commanding influence on; exercise control over.', 'Hukmronlik qilmoq, yetakchilik qilmoq', 'Доминировать, господствовать', 'A few massive multinational corporations currently dominate the global smartphone market.', 'Hozirda bir nechta yirik transmilliy korporatsiyalar jahon smartfon bozorida hukmronlik qilmoqda.', '["dominate the market","dominate the game","dominate the conversation"]'::jsonb, '["control","rule","command","lead"]'::jsonb, 148),
  ('Edible', 8, 'adjective', '/ˈed.ə.bəl/', 'Fit to be safely eaten; not poisonous.', 'Yeyishli, iste''molga yaroqli', 'Съедобный', 'Never pick wild mushrooms in the forest unless you are completely certain they are edible.', 'O''rmonda yovvoyi qo''ziqorinlarni yeyishga yaroqli ekaniga to''liq ishonchingiz komil bo''lmaguncha aslo termang.', '["edible fruit","edible oils","barely edible"]'::jsonb, '["safe to eat","consumable","wholesome"]'::jsonb, 149),
  ('Hostile', 8, 'adjective', '/ˈhɒs.taɪl/', 'Unfriendly; antagonistic; opposed to someone or something.', 'Dushmanona, adovatli', 'Враждебный, неприязненный', 'Explorers faced extreme dangers while trekking across the bitterly cold, hostile Arctic wilderness.', 'Sayyohlar qahraton sovuq, dushmanona Arktika dashtlaridan o''tishda o''ta xavfli vaziyatlarga duch keldilar.', '["hostile environment","hostile reaction","hostile takeover"]'::jsonb, '["unfriendly","antagonistic","aggressive","belligerent"]'::jsonb, 150),
  ('Intake', 8, 'noun', '/ˈɪn.teɪk/', 'An amount of food, air, or another substance taken into the body.', 'Iste''mol miqdori, qabul qilingan ozuqa', 'Потребление, прием (пищи)', 'Nutritionists strongly recommend reducing your daily intake of refined sugars and sodium.', 'Parhezshunoslar tozalangan shakar va natriyning kunlik iste''mol miqdorini kamaytirishni qat''iy tavsiya qiladilar.', '["daily intake","caloric intake","water intake"]'::jsonb, '["consumption","absorption","ingestion"]'::jsonb, 151),
  ('Likewise', 8, 'adverb', '/ˈlaɪk.waɪz/', 'In the same way; similarly; also.', 'Shuningdek, xuddi shunday', 'Также, аналогично, взаимно', 'The math teacher was impressed by Sardor''s analytical essay, and his classmates felt likewise.', 'Matematika o''qituvchisi Sardorning tahliliy inshosidan hayratda qoldi va sinfdoshlari ham xuddi shunday his qildilar.', '["feel likewise","do likewise","respond likewise"]'::jsonb, '["similarly","equally","in like manner","too"]'::jsonb, 152),
  ('Malnutrition', 8, 'noun', '/ˌmæl.njuːˈtrɪʃ.ən/', 'Lack of proper nutrition, caused by not having enough to eat or not eating the right foods.', 'To''yib ovqatlanmaslik, ozuqa yetishmovchiligi', 'Недоедание, неполноценное питание', 'Severe childhood malnutrition stunts physical growth and hinders normal cognitive development.', 'Bolalikdagi og''ir to''yib ovqatlanmaslik jismoniy o''sishni to''xtatadi va normal aqliy rivojlanishga to''sqinlik qiladi.', '["suffer from malnutrition","combat malnutrition","acute malnutrition"]'::jsonb, '["undernourishment","starvation","deficiency"]'::jsonb, 153),
  ('Medication', 8, 'noun', '/ˌmed.ɪˈkeɪ.ʃən/', 'A substance used for medical treatment, especially a drug or group of drugs.', 'Dori-darmon, dori vositasi', 'Лекарство, медикаменты', 'The doctor emphasized that the patient must take the prescribed blood pressure medication on time.', 'Shifokor bemor qon bosimiga qarshi yozilgan dori-darmonni o''z vaqtida qabul qilishi shartligini ta''kidladi.', '["take medication","prescribed medication","pain medication"]'::jsonb, '["medicine","drug","prescription","remedy"]'::jsonb, 154),
  ('Misconception', 8, 'noun', '/ˌmɪs.kənˈsep.ʃən/', 'A view or opinion that is incorrect because based on faulty thinking or understanding.', 'Noto''g''ri tushuncha, yanglish fikr', 'Заблуждение, неправильное представление', 'It is a common misconception that reading faster automatically decreases comprehension.', 'Tezroq o''qish avtomatik ravishda matnni tushunishni pasaytiradi degan fikr keng tarqalgan noto''g''ri tushunchadir.', '["common misconception","dispel a misconception","popular misconception"]'::jsonb, '["delusion","fallacy","misunderstanding","false belief"]'::jsonb, 155),
  ('Obscure', 8, 'adjective', '/əbˈskjʊər/', 'Not discovered or known about; uncertain; difficult to understand.', 'Noma''lum, tushunarsiz, noaniq', 'Малоизвестный, неясный, смутный', 'The historian discovered an obscure 15th-century manuscript tucked away in the archives.', 'Tarixchi arxivlar tubida yashiringan 15-asrga oid kam ma''lum bo''lgan qadimiy qo''lyozmani topdi.', '["obscure origins","obscure reference","remain obscure"]'::jsonb, '["unclear","vague","little-known","mysterious"]'::jsonb, 156),
  ('Oppress', 8, 'verb', '/əˈpres/', 'To keep someone in subservience and hardship, especially by the unjust exercise of authority.', 'Zulm qilmoq, ezmoq', 'Угнетать, притеснять', 'The authoritarian dictator used brutal police force to oppress the innocent population.', 'Avtoritar diktator begunoh aholiga zulm qilish uchun shafqatsiz politsiya kuchidan foydalandi.', '["oppress the poor","oppress minorities","feel oppressed"]'::jsonb, '["persecute","tyrannize","subjugate","maltreat"]'::jsonb, 157),
  ('Peel', 8, 'verb', '/piːl/', 'To remove the outer covering or skin from a fruit, vegetable, or other item.', 'Po''stini archmoq, tozalamoq', 'Чистить, сдирать кожуру', 'Please carefully peel the oranges and slice them neatly for the fruit salad.', 'Iltimos, apelsinlarning po''stini ehtiyotkorlik bilan arching va mevali salat uchun chiroyli qilib to''g''rang.', '["peel potatoes","peel off","banana peel"]'::jsonb, '["skin","pare","strip","shave"]'::jsonb, 158),
  ('Prescription', 8, 'noun', '/prɪˈskrɪp.ʃən/', 'An instruction written by a medical practitioner that authorizes a patient to be provided with a medicine.', 'Shifokor retsepti, retsept', 'Рецепт (врачебный), предписание', 'You cannot purchase strong antibiotics at the local pharmacy without a valid doctor''s prescription.', 'Mahalliy dorixonada shifokorning amaldagi retseptisiz kuchli antibiotiklarni sotib ololmaysiz.', '["write a prescription","fill a prescription","prescription drugs"]'::jsonb, '["doctor''s order","recipe","instruction","remedy"]'::jsonb, 159),
  ('Respirator', 8, 'noun', '/ˈres.pɪ.reɪ.tər/', 'An apparatus worn over the mouth and nose or that helps someone breathe.', 'Respirator, sun''iy nafas apparati', 'Респиратор, дыхательный аппарат', 'Miners wear a protective respirator to avoid inhaling toxic mineral dust underground.', 'Konchilar yer ostida zaharli mineral changini yutmaslik uchun himoya respiratorini taqadilar.', '["wear a respirator","medical respirator","protective respirator"]'::jsonb, '["gas mask","breathing apparatus","ventilator"]'::jsonb, 160),
  ('Strive', 8, 'verb', '/straɪv/', 'To make great efforts to achieve or obtain something; struggle.', 'Intilmoq, astoydil harakat qilmoq', 'Стремиться, прилагать усилия', 'Diligent IELTS students constantly strive for academic excellence and vocabulary mastery.', 'Tirishqoq IELTS talabalari doimo akademik yuksaklikka va so''z boyligini puxta egallashga intiladilar.', '["strive for success","strive to achieve","strive against"]'::jsonb, '["endeavor","struggle","aspire","aim"]'::jsonb, 161),
  ('Archaic', 9, 'adjective', '/ɑːˈkeɪ.ɪk/', 'Very old or old-fashioned; belonging to an earlier period in history.', 'Qadimiy, eskirgan, arxaik', 'Архаичный, устарелый', 'The legal document contained archaic phrasing that baffled modern law students.', 'Yuridik hujjatda zamonaviy huquqshunos talabalarni hayratga solgan eskirgan so''z birikmalari mavjud edi.', '["archaic language","archaic law","archaic system"]'::jsonb, '["obsolete","ancient","antiquated","outdated"]'::jsonb, 162),
  ('Benevolent', 9, 'adjective', '/bəˈnev.əl.ənt/', 'Well meaning and kindly; serving a charitable rather than profit-making purpose.', 'Saxovatli, mehribon, xayrixoh', 'Великодушный, благожелательный, благотворительный', 'The benevolent billionaire donated millions of dollars to build free cancer clinics.', 'Saxovatli milliarder bepul saraton klinikalarini qurish uchun millionlab dollar xayriya qildi.', '["benevolent leader","benevolent donor","benevolent smile"]'::jsonb, '["kind","generous","charitable","magnanimous"]'::jsonb, 163),
  ('Brass', 9, 'noun', '/brɑːs/', 'A yellow alloy of copper and zinc, often used for musical instruments and decorative objects.', 'Jez, latun (sariq metall)', 'Латунь, медь; духовые инструменты', 'The orchestra''s brass section, featuring trumpets and trombones, sounded triumphant.', 'Orkestrning truba va trombonlardan iborat jez cholg''ulari bo''limi g''olibona yangradi.', '["brass instrument","brass band","polished brass"]'::jsonb, '["alloy","copper-zinc","metallic bronze"]'::jsonb, 164),
  ('Capitalism', 9, 'noun', '/ˈkæp.ɪ.təl.ɪ.zəm/', 'An economic and political system in which a country''s trade and industry are controlled by private owners for profit.', 'Kapitalizm, bozor iqtisodiyoti', 'Капитализм', 'Free-market capitalism fosters entrepreneurial innovation, competition, and economic efficiency.', 'Erkin bozor kapitalizmi tadbirkorlik innovatsiyasini, raqobatni va iqtisodiy samaradorlikni rivojlantiradi.', '["global capitalism","free-market capitalism","rise of capitalism"]'::jsonb, '["free enterprise","private enterprise","market economy"]'::jsonb, 165),
  ('Component', 9, 'noun', '/kəmˈpəʊ.nənt/', 'A part or element of a larger whole, especially a machine or system.', 'Tarkibiy qism, bo''lak, komponent', 'Компонент, составная часть', 'Regular active vocabulary revision is a critical component of successful IELTS preparation.', 'Lug''at boyligini muntazam faol takrorlash muvaffaqiyatli IELTS tayyorgarligining muhim tarkibiy qismidir.', '["vital component","key component","electronic components"]'::jsonb, '["part","element","constituent","ingredient"]'::jsonb, 166),
  ('Dependence', 9, 'noun', '/dɪˈpen.dəns/', 'The state of relying on or being controlled by someone or something else.', 'Qaramlik, bog''liqlik', 'Зависимость', 'Many developed nations are striving to decrease their heavy dependence on imported fossil fuels.', 'Ko''plab rivojlangan davlatlar import qilinadigan qazilma yoqilg''ilarga kuchli qaramlikni kamaytirishga intilmoqdalar.', '["heavy dependence","economic dependence","reduce dependence"]'::jsonb, '["reliance","addiction","subjection","contingency"]'::jsonb, 167),
  ('Diminish', 9, 'verb', '/dɪˈmɪn.ɪʃ/', 'To make or become less; reduce in size, extent, or importance.', 'Kamaymoq, qisqarmoq, pasaymoq', 'Уменьшать, ослаблять, снижаться', 'His intense enthusiasm for the project began to diminish after repeated budget cuts.', 'Kompaniyadagi takroriy byudjet qisqartirishlaridan so''ng uning loyihaga bo''lgan kuchli ishtiyoqi so''na boshladi.', '["diminish over time","diminish in value","diminish returns"]'::jsonb, '["decrease","lessen","shrink","decline"]'::jsonb, 168),
  ('Drawback', 9, 'noun', '/ˈdrɔː.bæk/', 'A feature that renders something less acceptable; a disadvantage or problem.', 'Kamchilik, salbiy jihat, nuqson', 'Недостаток, изъян, минус', 'The main drawback of living in a bustling megacity is the suffocating traffic congestion.', 'Katta gavjum megapolisda yashashning asosiy kamchiligi bu bo''g''uvchi tirbandliklardir.', '["major drawback","suffer from a drawback","weigh drawbacks"]'::jsonb, '["disadvantage","downside","shortcoming","flaw"]'::jsonb, 169),
  ('Fad', 9, 'noun', '/fæd/', 'An intense and widely shared enthusiasm for something, especially one that is short-lived; a craze.', 'Vaqtinchalik moda, o''tkinchi qiziqish', 'Причуда, преходящее увлечение, писк моды', 'Many strict internet diets turn out to be nothing more than a passing celebrity fad.', 'Internetdagi ko''plab qat''iy parhezlar vaqtinchalik yulduzlar modasidan boshqa narsa emasligi ma''lum bo''ladi.', '["passing fad","latest fad","health fad"]'::jsonb, '["craze","vogue","trend","mania"]'::jsonb, 170),
  ('Impose', 9, 'verb', '/ɪmˈpəʊz/', 'To force an unwelcome decision, tax, or law to be accepted or put in place.', 'Yuklamoq, majburan joriy qilmoq', 'Накладывать, облагать, навязывать', 'The United Nations voted to impose strict trade sanctions on the aggressive regime.', 'Birlashgan Millatlar Tashkiloti tajovuzkor tuzumga nisbatan qat''iy savdo sanksiyalarini joriy qilish uchun ovoz berdi.', '["impose sanctions","impose a ban","impose restrictions"]'::jsonb, '["enforce","levy","inflict","foist"]'::jsonb, 171),
  ('Managerial', 9, 'adjective', '/ˌmæn.əˈdʒɪə.ri.əl/', 'Relating to management or managers; administrative.', 'Boshqaruvga oid, rahbarlikka oid', 'Управленческий, административный', 'Promoting her to a senior managerial role recognized her exceptional leadership qualities.', 'Uni yuqori boshqaruv lavozimiga ko''tarish uning ajoyib yetakchilik qobiliyatlarini e''tirof etdi.', '["managerial skills","managerial position","managerial responsibilities"]'::jsonb, '["administrative","executive","supervisory","directorial"]'::jsonb, 172),
  ('Medieval', 9, 'adjective', '/ˌmed.iˈiː.vəl/', 'Relating to the Middle Ages in European history (roughly 500–1500 AD).', 'O''rta asrlarga oid, o''rta asriy', 'Средневековый', 'Tourists marveled at the imposing stone walls of the preserved medieval castle in Prague.', 'Sayyohlar Pragadagi saqlanib qolgan o''rta asrlarga oid qasrning mahobatli tosh devorlariga qarab hayratga tushdilar.', '["medieval history","medieval castle","medieval manuscripts"]'::jsonb, '["Middle Ages","Gothic","feudal","ancient"]'::jsonb, 173),
  ('Obsolete', 9, 'adjective', '/ˌɒb.səˈliːt/', 'No longer produced or used; out of date.', 'Eskirgan, iste''moldan chiqqan', 'Устаревший, вышедший из употребления', 'Smartphones with touchscreens made traditional keypad cellphones practically obsolete.', 'Sensorli ekranli smartfonlar an''anaviy tugmachali telefonlarni amalda iste''moldan chiqardi.', '["render obsolete","become obsolete","obsolete technology"]'::jsonb, '["outdated","archaic","disused","antiquated"]'::jsonb, 174),
  ('Peninsula', 9, 'noun', '/pəˈnɪn.sjə.lə/', 'A piece of land almost surrounded by water or projecting out into a body of water.', 'Yarimorol', 'Полуостров', 'Florida is a sunny American peninsula bordered by the Atlantic Ocean and the Gulf of Mexico.', 'Florida – Atlantika okeani va Meksika ko''rfazi bilan o''ralgan quyoshli Amerika yarimorolidir.', '["Arabian peninsula","rocky peninsula","narrow peninsula"]'::jsonb, '["cape","promontory","headland","spit"]'::jsonb, 175),
  ('Prestige', 9, 'noun', '/presˈtiːʒ/', 'Widespread respect and admiration felt for someone on the basis of a perception of their achievements or quality.', 'Obro''-e''tibor, nufuz', 'Престиж, авторитет', 'Winning the Nobel Prize in Physics confers immense worldwide prestige and scientific recognition.', 'Fizika bo''yicha Nobel mukofotini qo''lga kiritish ulkan jahon miqyosidagi nufuz va ilmiy e''tirof keltiradi.', '["immense prestige","gain prestige","lose prestige"]'::jsonb, '["reputation","status","esteem","renown"]'::jsonb, 176),
  ('Proportion', 9, 'noun', '/prəˈpɔː.ʃən/', 'A part, share, or number considered in comparative relation to a whole.', 'Nisbat, mutanosiblik, ulush', 'Пропорция, доля, соотношение', 'A significant proportion of university students work part-time jobs to pay tuition fees.', 'Universitet talabalarining katta bir qismi o''qish to''lovlarini qoplash uchun yarim stavkada ishlaydi.', '["in proportion to","large proportion","out of all proportion"]'::jsonb, '["percentage","ratio","share","fraction"]'::jsonb, 177),
  ('Radical', 9, 'adjective', '/ˈræd.ɪ.kəl/', 'Relating to or affecting the fundamental nature of something; far-reaching or thorough.', 'Tub, keskin, qat''iy', 'Радикальный, коренной', 'The ministry introduced radical reforms to modernize the national education curriculum.', 'Vazirlik milliy ta''lim dasturini modernizatsiya qilish uchun tub islohotlarni joriy qildi.', '["radical change","radical reform","radical departure"]'::jsonb, '["fundamental","drastic","profound","revolutionary"]'::jsonb, 178),
  ('Refute', 9, 'verb', '/rɪˈfjuːt/', 'To prove a statement or theory to be wrong or false; disprove.', 'Rad etmoq, noto''g''riligini isbotlamoq', 'Опровергать, доказывать несостоятельность', 'The defense lawyer presented solid video evidence to completely refute the false allegations.', 'Advokat soxta ayblovlarni butunlay rad etish uchun ishonchli video dalillarni taqdim etdi.', '["refute an argument","refute allegations","conclusively refute"]'::jsonb, '["disprove","debunk","rebut","invalidate"]'::jsonb, 179),
  ('Spectacular', 9, 'adjective', '/spekˈtæk.jə.lər/', 'Beautiful in a dramatic and eye-catching way; magnificent.', 'Hayratomuz, ko''zni qamashtiruvchi, ajoyib', 'Захватывающий, эффектный, зрелищный', 'The New Year celebration in Sydney concluded with a spectacular fireworks display over the harbor.', 'Sidneydagi Yangi yil bayrami ko''rfaz uzra ko''zni qamashtiruvchi mushakbozlik tomoshasi bilan yakunlandi.', '["spectacular view","spectacular fireworks","spectacular success"]'::jsonb, '["magnificent","dramatic","breathtaking","stunning"]'::jsonb, 180),
  ('Weave', 9, 'verb', '/wiːv/', 'To form fabric or a story by interlacing long threads or intricate plot lines.', 'To''qimoq, o''rmoq', 'Ткать, плести, слагать', 'Traditional Uzbek artisans weave exquisite silk ikat and atlas fabrics using ancient looms.', 'An''anaviy o''zbek hunarmandlari qadimiy dastgohlar yordamida nafis ipak ikat va atlas matolarini to''qiydilar.', '["weave silk","weave a story","weave a carpet"]'::jsonb, '["interlace","braid","knit","twine"]'::jsonb, 181),
  ('Accountant', 10, 'noun', '/əˈkaʊn.tənt/', 'A person whose job is to keep or inspect financial accounts and records.', 'Hisobchi, buxgalter', 'Бухгалтер', 'A certified chartered accountant analyzed the firm''s balance sheets before the annual audit.', 'Sertifikatlangan buxgalter yillik auditdan oldin kompaniyaning balans varaqalarini sinchiklab tahlil qildi.', '["chartered accountant","hire an accountant","tax accountant"]'::jsonb, '["bookkeeper","auditor","financial officer"]'::jsonb, 182),
  ('Capitalist', 10, 'noun', '/ˈkæp.ɪ.təl.ɪst/', 'A wealthy person who uses money to invest in trade and industry for profit in accordance with capitalism.', 'Kapitalist, yirik sarmoyador', 'Капиталист', 'The venture capitalist invested two million dollars into the promising artificial intelligence startup.', 'Venchur sarmoyadori istiqbolli sun''iy intellekt startapiga ikki million dollar investitsiya qildi.', '["venture capitalist","wealthy capitalist","capitalist system"]'::jsonb, '["investor","financier","tycoon","entrepreneur"]'::jsonb, 183),
  ('Contempt', 10, 'noun', '/kənˈtempt/', 'The feeling that a person or a thing is beneath consideration, worthless, or deserving scorn.', 'Nafrat, mensimaslik, jirkanish', 'Презрение, неуважение', 'The honest judge looked at the remorseless criminal with undisguised contempt.', 'Halol sudya tavba qilmagan jinoyatchiga yashirilmagan chuqur nafrat bilan qaradi.', '["hold in contempt","treat with contempt","beneath contempt"]'::jsonb, '["scorn","disdain","disrespect","loathing"]'::jsonb, 184),
  ('Dedicate', 10, 'verb', '/ˈded.ɪ.keɪt/', 'To devote time, effort, or oneself to a particular task or purpose.', 'Bag''ishlamoq, bag''ishlab o''tkazmoq', 'Посвящать, предназначать', 'Dr. Alimov decided to dedicate his entire medical career to finding treatments for rare diseases.', 'Doktor Alimov butun tibbiy faoliyatini kamyob kasalliklarni davolash yo''llarini topishga bag''ishlashga qaror qildi.', '["dedicate oneself to","dedicate time to","dedicate a book to"]'::jsonb, '["devote","commit","assign","pledge"]'::jsonb, 185),
  ('Ditch', 10, 'noun', '/dɪtʃ/', 'A narrow channel dug at the side of a road or field, to hold or carry away water.', 'Ariq, xandaq', 'Канава, ров', 'Heavy rain filled the roadside drainage ditch with rushing muddy water.', 'Kuchli yomg''ir yo''l chetidagi suv oqish arig''ini loyqa suv bilan to''ldirdi.', '["roadside ditch","drainage ditch","dig a ditch"]'::jsonb, '["trench","drain","gutter","channel"]'::jsonb, 186),
  ('Enterprise', 10, 'noun', '/ˈen.tə.praɪz/', 'A project or undertaking, especially a bold or complex one; a business or company.', 'Korxona, ishbilarmonlik, tashabbus', 'Предприятие, предприимчивость', 'Launching a clean energy startup is a bold and ambitious commercial enterprise.', 'Toza energiya startapini ishga tushirish jasoratli va ulkan tijorat korxonasidir.', '["commercial enterprise","joint enterprise","state enterprise"]'::jsonb, '["venture","undertaking","business","company"]'::jsonb, 187),
  ('Exquisite', 10, 'adjective', '/ɪkˈskwɪz.ɪt/', 'Extremely beautiful and delicate; crafted with supreme skill.', 'Nafis, latif, beqiyos', 'Изысканный, утонченный, превосходный', 'The bride wore a handmade wedding gown adorned with exquisite lace and pearls.', 'Kelin nafis to''r va marvaridlar bilan bezatilgan qo''lda tikilgan to''y libosini kiygan edi.', '["exquisite taste","exquisite craftsmanship","exquisite beauty"]'::jsonb, '["delicate","fine","superb","magnificent"]'::jsonb, 188),
  ('Finance', 10, 'noun', '/ˈfaɪ.næns/', 'The management of large amounts of money, especially by governments or large companies.', 'Moliya, pul muomalasi', 'Финансы, финансовое дело', 'He pursued a master''s degree in corporate finance to prepare for investment banking.', 'U investitsiya bankchiligiga tayyorgarlik ko''rish uchun korporativ moliya bo''yicha magistraturada o''qidi.', '["minister of finance","personal finance","corporate finance"]'::jsonb, '["funds","money management","capital","economics"]'::jsonb, 189),
  ('Indifferent', 10, 'adjective', '/ɪnˈdɪf.ər.ənt/', 'Having no particular interest or sympathy; unconcerned and apathetic.', 'Befarq, loqayd', 'Равнодушный, безразличный', 'It is dangerous for citizens to remain completely indifferent to local political issues.', 'Fuqarolarning mahalliy siyosiy masalalarga butunlay befarq bo''lib qolishi xavflidir.', '["indifferent to","remain indifferent","indifferent attitude"]'::jsonb, '["unconcerned","apathetic","detached","uninterested"]'::jsonb, 190),
  ('Irrigate', 10, 'verb', '/ˈɪr.ɪ.ɡeɪt/', 'To supply water to land or crops to help growth, typically by means of channels.', 'Sug''ormoq, suv taramoq', 'Орошать, поливать', 'Farmers in the Fergana Valley construct canals to efficiently irrigate their cotton fields.', 'Farg''ona vodiysi fermerlari paxta maydonlarini samarali sug''orish uchun kanallar quradilar.', '["irrigate crops","irrigate farmland","irrigate fields"]'::jsonb, '["water","flood","inundate","moisten"]'::jsonb, 191),
  ('Maximize', 10, 'verb', '/ˈmæk.sɪ.maɪz/', 'To make as large or great as possible; make the best use of.', 'Eng yuqori darajaga yetkazmoq, maksimal qilmoq', 'Максимизировать, доводить до максимума', 'Effective IELTS study techniques maximize your memorization efficiency while saving time.', 'Samarali IELTS o''rganish usullari vaqtni tejagan holda yodda saqlash samaradorligini maksimal oshiradi.', '["maximize profits","maximize potential","maximize efficiency"]'::jsonb, '["optimize","increase to the max","boost","magnify"]'::jsonb, 192),
  ('Monetary', 10, 'adjective', '/ˈmʌn.ɪ.tri/', 'Relating to money or currency.', 'Pulga oid, pul-kreditga oid', 'Денежный, валютный, монетарный', 'The Central Bank adjusted interest rates as part of its prudent monetary policy.', 'Markaziy bank o''zining ehtiyotkorona pul-kredit siyosatining bir qismi sifatida foiz stavkalarini moslashtirdi.', '["monetary policy","monetary value","monetary fund"]'::jsonb, '["financial","fiscal","pecuniary","cash"]'::jsonb, 193),
  ('Precaution', 10, 'noun', '/prɪˈkɔː.ʃən/', 'A measure taken in advance to prevent something dangerous, unpleasant, or inconvenient from happening.', 'Ehtiyot chorasi', 'Предосторожность, мера предосторожности', 'Wearing a helmet while riding a bicycle is an essential safety precaution.', 'Velosipedda yurganda shlem taqish hayotiy muhim xavfsizlik ehtiyot chorasidir.', '["take precautions","safety precautions","as a precaution"]'::jsonb, '["safeguard","preventive measure","protection","insurance"]'::jsonb, 194),
  ('Preliminary', 10, 'adjective', '/prɪˈlɪm.ɪ.nər.i/', 'Denoting an action or event preceding or done in preparation for something more full or important.', 'Dastlabki, boshlang''ich', 'Предварительный', 'The preliminary examination results suggest that the experimental vaccine is highly effective.', 'Dastlabki tekshiruv natijalari tajribaviy vaksinaning yuqori darajada samarali ekanligini ko''rsatmoqda.', '["preliminary results","preliminary investigation","preliminary round"]'::jsonb, '["initial","introductory","preparatory","prior"]'::jsonb, 195),
  ('Saturate', 10, 'verb', '/ˈsætʃ.ər.eɪt/', 'To cause something to become thoroughly soaked with liquid so that no more can be absorbed.', 'To''yintirmoq, butunlay ho''llamoq', 'Насыщать, пропитывать', 'The torrential afternoon downpour saturated the soil, creating large puddles across the garden.', 'Tushdan keyingi kuchli jala tuproqni suvga to''yintirdi va butun bog''da katta ko''lmaklar hosil qildi.', '["saturate the market","saturated fat","saturate the soil"]'::jsonb, '["soak","drench","steep","imbue"]'::jsonb, 196),
  ('Simplicity', 10, 'noun', '/sɪmˈplɪs.ə.ti/', 'The quality or condition of being easy to understand or do; freedom from complexity.', 'Oddiylik, soddalik', 'Простота, легкость', 'The beauty of Apple''s user interface design lies in its elegance, clarity, and simplicity.', 'Apple foydalanuvchi interfeysi dizaynining go''zalligi uning nafisligi, ravshanligi va soddaligidadir.', '["for simplicity''s sake","breathtaking simplicity","elegant simplicity"]'::jsonb, '["clarity","easiness","plainness","directness"]'::jsonb, 197),
  ('Sow', 10, 'verb', '/səʊ/', 'To plant seeds by scattering them on or in the earth.', 'Ekkmoq, urug'' sepmoq', 'Сеять, засевать', 'In early spring, farmers sow wheat seeds across the freshly plowed fields.', 'Erta bahorda fermerlar yangi haydalgan dalalar bo''ylab bug''doy urug''ini sepadilar.', '["sow seeds","sow doubt","reap what you sow"]'::jsonb, '["plant","seed","scatter","disperse"]'::jsonb, 198),
  ('Soy', 10, 'noun', '/sɔɪ/', 'A protein-rich bean used to make food products, oil, milk, and tofu.', 'Soya', 'Соя', 'Soy milk and tofu are nutritious protein-rich alternatives for vegetarians.', 'Soya suti va tofi vegetarianlar uchun oqsilga boy to''yimli ozuqa o''rnini bosadi.', '["soy sauce","soy milk","soy protein"]'::jsonb, '["soybean","soya"]'::jsonb, 199),
  ('Spade', 10, 'noun', '/speɪd/', 'A tool with a sharp-edged, typically rectangular, metal blade and a long handle, used for digging.', 'Belkurak, bel', 'Лопата, заступ', 'The gardener grabbed a sturdy spade to dig holes for planting new rose bushes.', 'Bog''bon yangi atirgul butalarini ekish uchun chuqur qazish maqsadida mustahkam belkurakni oldi.', '["call a spade a spade","garden spade","dig with a spade"]'::jsonb, '["shovel","trowel","digging tool"]'::jsonb, 200),
  ('Upcoming', 10, 'adjective', '/ˈʌpˌkʌm.ɪŋ/', 'Happening or appearing soon; forthcoming.', 'Kutilayotgan, yaqinlashayotgan, bo''lajak', 'Предстоящий, наступающий', 'Students are studying rigorously for their upcoming international IELTS examination.', 'Talabalar o''zlarining yaqinlashib kelayotgan xalqaro IELTS imtihoniga qizg''in tayyorgarlik ko''rmoqdalar.', '["upcoming events","upcoming release","upcoming election"]'::jsonb, '["forthcoming","approaching","imminent","future"]'::jsonb, 201),
  ('Acute', 11, 'adjective', '/əˈkjuːt/', 'Present or experienced to a severe or intense degree; sharp.', 'O''tkir, keskin, kuchli', 'Острый, резкий, проницательный', 'The patient complained of acute abdominal pain that began suddenly after dinner.', 'Bemor kechki ovqatdan keyin to''satdan boshlangan o''tkir qorin og''rig''idan shikoyat qildi.', '["acute pain","acute shortage","acute angle"]'::jsonb, '["sharp","severe","intense","critical"]'::jsonb, 202),
  ('Aggression', 11, 'noun', '/əˈɡreʃ.ən/', 'Hostile or violent behavior or feelings; readiness to attack or confront.', 'Tajovuzkorlik, agressiya', 'Агрессия, нападение', 'Unprovoked military aggression against sovereign neighboring states violates international law.', 'Suveren qo''shni davlatlarga qarshi asossiz harbiy tajovuz xalqaro huquqni buzadi.', '["act of aggression","show aggression","unprovoked aggression"]'::jsonb, '["hostility","belligerence","antagonism","violence"]'::jsonb, 203),
  ('Banquet', 11, 'noun', '/ˈbæŋ.kwɪt/', 'An elaborate and formal evening meal for many people, often followed by speeches.', 'Tantanali ziyofat, banket', 'Банкет, торжественный ужин', 'The university hosted a splendid banquet to celebrate the graduation of its top medical scholars.', 'Universitet o''zining eng yaxshi tibbiyot talabalari bitiruvini nishonlash uchun dabdabali tantanali ziyofat uyushtirdi.', '["state banquet","attend a banquet","banquet hall"]'::jsonb, '["feast","dinner","reception","formal meal"]'::jsonb, 204),
  ('Biography', 11, 'noun', '/baɪˈɒɡ.rə.fi/', 'An account of someone''s life written by someone else.', 'Biografiya, tarjimai hol', 'Биография, жизнеописание', 'The newly published biography of Steve Jobs offers an intimate look into his visionary mind.', 'Stiv Jobsning yangi nashr etilgan biografiyasi uning daho fikrlash olamiga yaqindan nazar soladi.', '["authorized biography","read a biography","write a biography"]'::jsonb, '["life story","memoir","profile","chronicle"]'::jsonb, 205),
  ('Boost', 11, 'verb', '/buːst/', 'To help or encourage something to increase, improve, or become more successful.', 'Oshirmoq, ko''tarmoq, kuchaytirmoq', 'Повышать, стимулировать, усиливать', 'Regular aerobic exercise and a nutritious diet help boost your immune system against viruses.', 'Muntazam jismoniy mashqlar va to''yimli ovqatlanish viruslarga qarshi immunitetingizni kuchaytirishga yordam beradi.', '["boost confidence","boost economy","boost morale"]'::jsonb, '["increase","enhance","elevate","lift"]'::jsonb, 206),
  ('Clap', 11, 'verb', '/klæp/', 'To strike the palms of one''s hands together repeatedly, typically in applause.', 'Qarsak chalmoq, olqishlamoq', 'Хлопать, аплодировать', 'The enthusiastic audience began to cheer and clap wildly after the pianist finished her solo.', 'Pianinochi o''z yakkaxon ijrosini tugatgach, g''ayratli tomoshabinlar qichqirib, jo''shqinlik bilan qarsak chala boshladilar.', '["clap hands","clap enthusiastically","thunder of clapping"]'::jsonb, '["applaud","cheer","acclaim"]'::jsonb, 207),
  ('Compel', 11, 'verb', '/kəmˈpel/', 'To force or oblige someone to do something.', 'Majbur qilmoq, undamoq', 'Принуждать, заставлять', 'Overwhelming factual evidence compelled the jury to find the defendant guilty.', 'Radd qilib bo''lmas faktik dalillar hay''at a''zolarini sudlanuvchini aybdor deb topishga majbur qildi.', '["feel compelled","compel someone to","circumstances compel"]'::jsonb, '["force","coerce","oblige","require"]'::jsonb, 208),
  ('Dominance', 11, 'noun', '/ˈdɒm.ɪ.nəns/', 'Power and influence over others; supreme control or supremacy.', 'Hukmronlik, ustunlik, yetakchilik', 'Господство, преобладание, доминирование', 'The software company maintained undisputed market dominance for over two decades.', 'Dasturiy ta''minot kompaniyasi yigirma yildan ortiq vaqt davomida bozorda shubhasiz hukmronlikni saqlab qoldi.', '["market dominance","global dominance","achieve dominance"]'::jsonb, '["supremacy","control","mastery","ascendancy"]'::jsonb, 209),
  ('Gorgeous', 11, 'adjective', '/ˈɡɔː.dʒəs/', 'Beautiful; very attractive and pleasing to the senses.', 'Juda go''zal, maftunkor, ko''rkam', 'Великолепный, прекрасный', 'We enjoyed a gorgeous sunset over the calm waters of the turquoise sea.', 'Biz feruza rangli dengizning sokin to''lqinlari uzra maftunkor quyosh botishidan zavqlandik.', '["gorgeous view","gorgeous dress","look gorgeous"]'::jsonb, '["stunning","striking","lovely","dazzling"]'::jsonb, 210),
  ('Inevitable', 11, 'adjective', '/ɪnˈev.ɪ.tə.bəl/', 'Certain to happen; unavoidable.', 'Muqarrar, qochib bo''lmas', 'Неизбежный, неминуемый', 'Technological advancement and automation are an inevitable part of human industrial progress.', 'Texnologik rivojlanish va avtomatlashtirish insoniyat sanoat taraqqiyotining muqarrar qismidir.', '["inevitable consequence","inevitable result","accept the inevitable"]'::jsonb, '["unavoidable","inescapable","certain","fated"]'::jsonb, 211),
  ('Legacy', 11, 'noun', '/ˈleɡ.ə.si/', 'An amount of money or property left to someone in a will; something handed down by a predecessor.', 'Meros, qoldirilgan boylik', 'Наследие, наследство', 'Amir Timur left behind a legendary cultural and architectural legacy of world renown.', 'Amir Temur jahon miqyosida mashhur bo''lgan afsonaviy madaniy va me''moriy meros qoldirdi.', '["cultural legacy","leave a legacy","lasting legacy"]'::jsonb, '["inheritance","heritage","endowment","bequest"]'::jsonb, 212),
  ('Masterpiece', 11, 'noun', '/ˈmɑː.stə.piːs/', 'A work of outstanding artistry, skill, or workmanship.', 'Shoh asar, durdona', 'Шедевр', 'Leonardo da Vinci''s Mona Lisa is celebrated as an unrivaled Renaissance masterpiece.', 'Leonardo da Vinchining ''Mona Liza'' asari Uyg''onish davrining tengsiz shoh asari sifatida e''zozlanadi.', '["artistic masterpiece","literary masterpiece","paint a masterpiece"]'::jsonb, '["magnum opus","classic","tour de force","work of art"]'::jsonb, 213),
