  ('Partiality', 11, 'noun', '/ˌpɑː.ʃiˈæl.ə.ti/', 'Unfair bias in favor of one thing over another; favoritism; a particular fondness.', 'Tarafkashlik, yon bosish, oshnolik', 'Пристрастие, предвзятость', 'A fair examiner must never show partiality toward any student during oral evaluations.', 'Adolatli imtihon oluvchi og''zaki baholashda hech qachon biron bir talabaga tarafkashlik ko''rsatmasligi shart.', '["show partiality","partiality towards","free from partiality"]'::jsonb, '["bias","favoritism","prejudice","preference"]'::jsonb, 219),
  ('Spontaneous', 11, 'adjective', '/spɒnˈteɪ.ni.əs/', 'Performed or occurring as a result of a sudden inner impulse and without premeditation or external stimulus.', 'O''z-o''zidan paydo bo''ladigan, bexosdan qilingan', 'Спонтанный, стихийный, самопроизвольный', 'The entire stadium erupted into spontaneous applause when the youngest runner crossed the finish line.', 'Eng yosh yuguruvchi marra chizig''ini kesib o''tganda butun stadion o''z-o''zidan jo''shqin qarsaklarga to''lib ketdi.', '["spontaneous decision","spontaneous applause","spontaneous reaction"]'::jsonb, '["unplanned","impromptu","instinctive","voluntary"]'::jsonb, 220),
  ('Virtue', 11, 'noun', '/ˈvɜː.tʃuː/', 'Behavior showing high moral standards; goodness and integrity.', 'Fazilat, yuksak axloqiylik', 'Добродетель, достоинство', 'Patience and humility are universal virtues valued in every great civilization.', 'Sabr-toqat va kamtarlik har bir buyuk tamaddunda qadrlanadigan umuminsoniy fazilatlardir.', '["by virtue of","make a virtue of","cardinal virtues"]'::jsonb, '["goodness","morality","integrity","righteousness"]'::jsonb, 221),
  ('Anthropology', 12, 'noun', '/ˌæn.θrəˈpɒl.ə.dʒi/', 'The study of human societies, cultures, and their historical development.', 'Antropologiya, odamshunoslik fani', 'Антропология', 'Cultural anthropology examines rituals and traditions across diverse global tribes.', 'Madaniy antropologiya turli xil global qabilalar bo''ylab marosim va an''analarni o''rganadi.', '["cultural anthropology","biological anthropology","study anthropology"]'::jsonb, '["study of humankind","ethnology","human sciences"]'::jsonb, 222),
  ('Applaud', 12, 'verb', '/əˈplɔːd/', 'To show approval or praise by clapping hands.', 'Olqishlamoq, qarsak chalmoq', 'Аплодировать, одобрять', 'The whole auditorium stood up to warmly applaud the visiting guest lecturer.', 'Butun auditoriya tashrif buyurgan mehmon o''qituvchini iliq olqishlash uchun o''rnidan turdi.', '["applaud wildly","applaud the effort","stand to applaud"]'::jsonb, '["clap","cheer","praise","acclaim"]'::jsonb, 223),
  ('Appoint', 12, 'verb', '/əˈpɔɪnt/', 'To assign a job or role to someone officially.', 'Tayinlamoq, lavozimga tayinlamoq', 'Назначать (на должность)', 'The board of directors voted unanimously to appoint Nigora as the new chief executive officer.', 'Direktorlar kengashi Nigorani yangi bosh ijrochi direktor etib tayinlash uchun bir ovozdan ovoz berdi.', '["appoint someone to","appoint a committee","duly appointed"]'::jsonb, '["assign","designate","nominate","name"]'::jsonb, 224),
  ('Compatible', 12, 'adjective', '/kəmˈpæt.ə.bəl/', 'Able to exist, live, or work together without problems or conflict.', 'Mos, bir-biriga tushadigan', 'Совместимый', 'Ensure your new graphics software is fully compatible with the computer''s operating system.', 'Yangi grafik dasturingiz kompyuterning operatsion tizimiga to''liq mos kelishiga ishonch hosil qiling.', '["compatible with","backward compatible","highly compatible"]'::jsonb, '["consistent","harmonious","congruous","adaptable"]'::jsonb, 225),
  ('Competence', 12, 'noun', '/ˈkɒm.pɪ.təns/', 'The ability to do something successfully or efficiently; capability.', 'Layoqat, malaka, qobiliyat', 'Компетентность, способность', 'The job interview rigorously tested the candidate''s professional competence and coding fluency.', 'Ish suhbati nomzodning kasbiy malakasi va dasturlash erkinligini sinchiklab tekshirdi.', '["linguistic competence","professional competence","demonstrate competence"]'::jsonb, '["ability","capability","proficiency","skill"]'::jsonb, 226),
  ('Confer', 12, 'verb', '/kənˈfɜːr/', 'To grant or bestow a title, degree, benefit, or right; to consult together.', 'Baxsh etmoq, taqdim etmoq; maslahatlashmoq', 'Присваивать, даровать; совещаться', 'The university will confer honorary doctorates upon two Nobel laureates this spring.', 'Universitet shu bahorda ikki Nobel mukofoti laureatiga faxriy doktorlik unvonini taqdim etadi.', '["confer a degree","confer with colleagues","confer an honor"]'::jsonb, '["bestow","grant","award","consult"]'::jsonb, 227),
  ('Consecutive', 12, 'adjective', '/kənˈsek.jə.tɪv/', 'Following continuously; in unbroken or logical sequence.', 'Ketma-ket, birin-ketin', 'Последовательный, подряд', 'The star tennis player won the Grand Slam tournament for three consecutive years.', 'Yulduz tennischi Katta Dubulg''a turnirida ketma-ket uch yil g''olib chiqdi.', '["consecutive days","consecutive wins","in consecutive order"]'::jsonb, '["successive","continuous","sequential","unbroken"]'::jsonb, 228),
  ('Crude', 12, 'adjective', '/kruːd/', 'In a natural or raw state; not yet processed or refined; also simple and rough.', 'Xom, ishlov berilmagan; qo''pol', 'Сырой, необработанный; грубый', 'Refineries heat crude oil at high temperatures to produce gasoline, diesel, and kerosene.', 'Zavodlar benzin, dizel va kerosin ishlab chiqarish uchun xom neftni yuqori haroratda qizdiradilar.', '["crude oil","crude methods","crude estimate"]'::jsonb, '["raw","unrefined","primitive","rough"]'::jsonb, 229),
  ('Cube', 12, 'noun', '/kjuːb/', 'A symmetrical three-dimensional shape, either solid or hollow, contained by six equal squares.', 'Kub, kub shaklidagi jism', 'Куб, кубик', 'She placed an ice cube into her refreshing glass of freshly squeezed lemonade.', 'U yangi siqilgan tetiklashtiruvchi limonad stakaniga muz kubikini tashladi.', '["ice cube","sugar cube","Rubik''s cube"]'::jsonb, '["block","square solid","hexahedron"]'::jsonb, 230),
  ('Feedback', 12, 'noun', '/ˈfiːd.bæk/', 'Information about reactions to a product, a person''s performance of a task, used as a basis for improvement.', 'Qayta aloqa, fikr-mulohaza', 'Обратная связь, отзыв', 'Constructive feedback from your IELTS tutor helps you identify and eliminate grammar errors.', 'IELTS ustozingizning foydali fikr-mulohazalari grammatik xatolarni aniqlash va yo''qotishga yordam beradi.', '["positive feedback","constructive feedback","give feedback"]'::jsonb, '["response","comments","evaluation","critique"]'::jsonb, 231),
  ('Ignorance', 12, 'noun', '/ˈɪɡ.nər.əns/', 'Lack of knowledge, education, or awareness.', 'Johillik, bilimsizlik, bexabarlik', 'Невежество, незнание', 'Spreading scientific education is the most effective weapon against prejudice, fear, and ignorance.', 'Ilmiy ma''rifatni yoyish xurofot, qo''rquv va johillikka qarshi eng samarali quroldir.', '["state of ignorance","blissful ignorance","plead ignorance"]'::jsonb, '["unawareness","illiteracy","inexperience","darkness"]'::jsonb, 232),
  ('Masculine', 12, 'adjective', '/ˈmæs.kjə.lɪn/', 'Having qualities or appearance traditionally associated with men.', 'Erkakcha, erkaklarga xos', 'Мужественный, мужской', 'The cologne had a crisp, masculine fragrance with hints of cedarwood and spice.', 'Atir sadr yog''ochi va ziravorlar iforini eslatuvchi tetiklantiruvchi, erkaklarga xos iforga ega edi.', '["masculine features","masculine voice","masculine traits"]'::jsonb, '["manly","virile","male","robust"]'::jsonb, 233),
  ('Monument', 12, 'noun', '/ˈmɒn.jə.mənt/', 'A statue, building, or other structure erected to commemorate a famous person or event.', 'Yodgorlik, obida, haykal', 'Памятник, монумент', 'The historic monument in Registan Square honors the golden age of scientific discovery.', 'Registon maydonidagi tarixiy obida ilmiy kashfiyotlarning oltin asrini ulug''laydi.', '["historic monument","erect a monument","national monument"]'::jsonb, '["memorial","statue","shrine","cenotaph"]'::jsonb, 234),
  ('Muscular', 12, 'adjective', '/ˈmʌs.kjə.lər/', 'Having well-developed muscles; strong and brawny.', 'Mushakdor, baquvvat, gavdali', 'Мускулистый, мускульный', 'Weightlifters maintain a remarkably muscular physique through dedicated daily training and protein intake.', 'Og''ir atletikachilar kunlik mashg''ulotlar va oqsil iste''moli orqali nihoyatda baquvvat mushakdor qomatni saqlaydilar.', '["muscular build","muscular system","muscular dystrophy"]'::jsonb, '["brawny","burly","sinewy","athletic"]'::jsonb, 235),
  ('Posture', 12, 'noun', '/ˈpɒs.tʃər/', 'The position in which someone holds their body when standing or sitting.', 'Qad-qomat, gavdani tutish', 'Осанка, поза', 'Maintaining good upright posture while working at a computer desk prevents chronic back pain.', 'Kompyuter stolida ishlaganda qaddini to''g''ri tutish surunkali bel og''rig''ining oldini oladi.', '["good posture","poor posture","correct your posture"]'::jsonb, '["bearing","carriage","stance","pose"]'::jsonb, 236),
  ('Situate', 12, 'verb', '/ˈsɪtʃ.u.eɪt/', 'To fix or build in a specified place or position; locate.', 'Joylashtirmoq, joylashmoq', 'Располагать, помещать', 'The university decided to situate its new biotechnology laboratory on the north campus.', 'Universitet o''zining yangi biotexnologiya laboratoriyasini shimoliy kampusda joylashtirishga qaror qildi.', '["situate near","conveniently situated","ideally situated"]'::jsonb, '["locate","position","place","site"]'::jsonb, 237),
  ('Supervise', 12, 'verb', '/ˈsuː.pə.vaɪz/', 'To observe and direct the execution of a task, project, or activity.', 'Nazorat qilmoq, kuzatmoq', 'Контролировать, руководить, надзирать', 'A senior certified civil engineer was hired to supervise construction of the suspension bridge.', 'Osma ko''prik qurilishini nazorat qilish uchun katta toifali muhandis yollangan edi.', '["supervise staff","closely supervise","supervise work"]'::jsonb, '["oversee","manage","direct","monitor"]'::jsonb, 238),
  ('Symmetry', 12, 'noun', '/ˈsɪm.ə.tri/', 'The quality of being made up of exactly similar parts facing each other or around an axis.', 'Simmetriya, mutanosiblik', 'Симметрия, соразмерность', 'The breathtaking architectural symmetry of the Taj Mahal reflects master geometric design.', 'Toj Mahalning hayratlanarli me''moriy simmetriyasi yuksak geometrik dizaynni aks ettiradi.', '["perfect symmetry","bilateral symmetry","lack of symmetry"]'::jsonb, '["balance","harmony","proportion","regularity"]'::jsonb, 239),
  ('Tattoo', 12, 'noun', '/təˈtuː/', 'A permanent mark or design made on the body by inserting pigment beneath the skin.', 'Tatuirovka, tatu', 'Татуировка, тату', 'Ancient sailors often got an anchor tattoo as a symbol of ocean voyages and endurance.', 'Qadimgi dengizchilar ko''pincha okean sayohatlari va matonat ramzi sifatida langar tatuirovkasini chizdirganlar.', '["get a tattoo","remove a tattoo","permanent tattoo"]'::jsonb, '["body art","ink","skin engraving"]'::jsonb, 240),
  ('Undergraduate', 12, 'noun', '/ˌʌn.dəˈɡrædʒ.u.ət/', 'A university student who has not yet received a first degree.', 'Bakalavr talabasi, talaba', 'Студент бакалавриата', 'Every undergraduate student is required to complete academic writing modules in their first year.', 'Har bir bakalavr talabasi birinchi kursida akademik yozuv modullarini tamomlashi shart.', '["undergraduate degree","undergraduate student","undergraduate studies"]'::jsonb, '["college student","first-degree student"]'::jsonb, 241),
  ('Brook', 13, 'noun', '/brʊk/', 'A small natural stream of fresh water.', 'Jilg''a, soy, kichik daryocha', 'Ручей', 'We stopped to rest beside a bubbling crystal-clear mountain brook.', 'Biz shildirab oqayotgan toshdek toza tog'' jilg''asi bo''yida dam olish uchun to''xtadik.', '["babbling brook","mountain brook","clear brook"]'::jsonb, '["stream","creek","rivulet","runnel"]'::jsonb, 242),
  ('Cater', 13, 'verb', '/ˈkeɪ.tər/', 'To provide food and drink, typically at social events; to satisfy a specific need.', 'Xizmat ko''rsatmoq, taom tayyorlab bermoq', 'Обслуживать, поставлять еду, угождать', 'Our vocabulary platform is specifically designed to cater to ambitious IELTS candidates.', 'Lug''at platformamiz yuqori maqsadli IELTS nomzodlarining ehtiyojlarini qondirish uchun maxsus ishlab chiqilgan.', '["cater to needs","cater an event","cater for a party"]'::jsonb, '["provide for","serve","accommodate","supply"]'::jsonb, 243),
  ('Considerate', 13, 'adjective', '/kənˈsɪd.ər.ət/', 'Carefully thinking about and respecting the feelings and needs of others.', 'E''tiborli, g''amxo''r, mulohazali', 'Внимательный, заботливый, чуткий', 'It was very considerate of him to offer his train seat to the pregnant lady.', 'Uning poyezddagi o''rindig''ini homilador ayolga bo''shatib bergani juda e''tiborli harakat edi.', '["be considerate of","considerate behavior","considerate host"]'::jsonb, '["thoughtful","attentive","kind","unselfish"]'::jsonb, 244),
  ('Consumption', 13, 'noun', '/kənˈsʌmp.ʃən/', 'The using up of a resource or the action of eating or drinking.', 'Iste''mol, sarflanish miqdori', 'Потребление, расход', 'Global industrial energy consumption has soared drastically over the past century.', 'Jahon sanoatining energiya iste''moli o''tgan asr davomida keskin ravishda oshib ketdi.', '["fuel consumption","energy consumption","public consumption"]'::jsonb, '["utilization","expenditure","usage","intake"]'::jsonb, 245),
  ('Criteria', 13, 'noun', '/kraɪˈtɪə.ri.ə/', 'Standards by which something may be judged or decided.', 'Mezonlar, baholash talablari', 'Критерии, стандарты', 'The selection criteria for the scholarship include GPA, leadership, and English proficiency.', 'Stipendiyani tanlash mezonlari o''rtacha baho, yetakchilik va ingliz tilini bilish darajasini o''z ichiga oladi.', '["selection criteria","meet the criteria","strict criteria"]'::jsonb, '["standards","benchmarks","measures","specifications"]'::jsonb, 246),
  ('Crust', 13, 'noun', '/krʌst/', 'The tough outer part of a loaf of bread, or the outermost solid shell of a rocky planet.', 'Qobiq, non po''sti; Yer qobig''i', 'Корка, земная кора', 'Earthquakes originate from movements within the tectonic plates of the Earth''s crust.', 'Zilzilalar Yer qobig''ining tektonik plitalari ichidagi harakatlardan kelib chiqadi.', '["Earth''s crust","bread crust","crispy crust"]'::jsonb, '["outer layer","shell","rind","surface"]'::jsonb, 247),
  ('Degrade', 13, 'verb', '/dɪˈɡreɪd/', 'To cause someone to lose respect; to break down or deteriorate chemically.', 'Kamsitmoq; parchalanish, chirimoq', 'Унижать; разрушаться, разлагаться', 'Conventional plastic bags take hundreds of years to naturally degrade in the soil.', 'Oddiy polietilen paketlar tuproqda tabiiy ravishda parchalanishi uchun yuzlab yillar ketadi.', '["degrade the environment","biodegrade","degrade human dignity"]'::jsonb, '["deteriorate","humiliate","break down","degenerate"]'::jsonb, 248),
  ('Entitle', 13, 'verb', '/ɪnˈtaɪ.təl/', 'To give someone a legal right or a just claim to receive or do something.', 'Huquq bermoq, haqli qilmoq', 'Давать право, уполномочивать', 'Purchasing an annual gym pass entitles members to access all swimming pools and saunas.', 'Yillik sport zali abonementini sotib olish a''zolarga barcha basseyn va saunalardan foydalanish huquqini beradi.', '["entitle to","be entitled to benefit","entitled to respect"]'::jsonb, '["qualify","authorize","license","allow"]'::jsonb, 249),
  ('Escort', 13, 'verb', '/ˈes.kɔːt/', 'To accompany someone or something somewhere, especially for protection or guidance.', 'Kuzatib bormoq, hamrohlik qilmoq', 'Сопровождать, эскортировать', 'Security guards were assigned to escort the visiting foreign ambassadors to the conference room.', 'Xavfsizlik soqchilari tashrif buyurgan xorijiy elchilarni anjuman zaliga kuzatib borish uchun biriktirildi.', '["police escort","escort safely","under armed escort"]'::jsonb, '["accompany","guide","conduct","usher"]'::jsonb, 250),
  ('External', 13, 'adjective', '/ɪkˈstɜː.nəl/', 'Belonging to or forming the outer surface or structure of something.', 'Tashqi, tashqaridagi', 'Внешний, наружный', 'The hard drive provides one terabyte of external storage for backing up essential files.', 'Ushbu qattiq disk muhim fayllarni zaxiralash uchun bir terabayt tashqi xotira beradi.', '["external hard drive","external factors","external examiner"]'::jsonb, '["outer","exterior","outside","outward"]'::jsonb, 251),
  ('Facility', 13, 'noun', '/fəˈsɪl.ə.ti/', 'A place, amenity, or piece of equipment provided for a particular purpose.', 'Inshoot, muassasa, qulaylik', 'Учреждение, объект, удобство', 'The new sports facility includes Olympic-standard swimming pools, tennis courts, and gymnasiums.', 'Yangi sport inshooti Olimpiya standartidagi suzish havzalari, tennis kortlari va zallarni o''z ichiga oladi.', '["medical facility","sports facility","state-of-the-art facility"]'::jsonb, '["amenity","complex","center","installation"]'::jsonb, 252),
  ('Faculty', 13, 'noun', '/ˈfæk.əl.ti/', 'A department or group of related departments in a university; or the teaching staff.', 'Fakultet, o''qituvchilar jamoasi', 'Факультет, профессорско-преподавательский состав', 'The faculty of engineering at Oxford University is renowned for cutting-edge robotics research.', 'Oksford universitetining muhandislik fakulteti ilg''or robototexnika tadqiqotlari bilan mashhur.', '["faculty members","faculty of law","distinguished faculty"]'::jsonb, '["academic staff","department","school","professors"]'::jsonb, 253),
  ('Heap', 13, 'noun', '/hiːp/', 'An untidy collection of things piled up haphazardly.', 'Uyum, to''da, g''aram', 'Куча, груда, ворох', 'A disorganized heap of textbooks, notes, and study flashcards covered his desk.', 'Darsliklar, qaydlar va kartochkalarning tartibsiz uyumi uning yozuv stolini qoplab yotardi.', '["heap of rubbish","heap of clothes","in a heap"]'::jsonb, '["pile","stack","mound","mass"]'::jsonb, 254),
  ('Hemisphere', 13, 'noun', '/ˈhem.ɪ.sfɪər/', 'A half of the earth, usually as divided into northern and southern halves by the equator.', 'Yarimshar (Yer sharining yarmi)', 'Полушарие', 'When it is winter in the northern hemisphere, summer blooms across the southern hemisphere.', 'Shimoliy yarimsharda qish bo''lganda, janubiy yarimsharda yoz gullab-yashnaydi.', '["northern hemisphere","southern hemisphere","brain hemisphere"]'::jsonb, '["half-globe","half-sphere"]'::jsonb, 255),
  ('Hound', 13, 'noun', '/haʊnd/', 'A type of hunting dog used for chasing game; also to pursue relentlessly.', 'Ov iti; tinimsiz ta''qib qilmoq', 'Гончая собака; преследовать', 'Hunters used swift hounds with an acute sense of scent to track foxes across the moor.', 'Ovchilar adirlar bo''ylab tulkilarni quvish uchun hidi o''tkir chaqqon ov itlaridan foydalandilar.', '["hound of the Baskervilles","bloodhound","hound by the press"]'::jsonb, '["hunting dog","canine","pursue","badger"]'::jsonb, 256),
  ('Impersonal', 13, 'adjective', '/ɪmˈpɜː.sən.əl/', 'Not influenced by, showing, or involving personal feelings or warmth; cold and clinical.', 'Sovuq, his-tuyg''usiz, shaxsiy bo''lmagan', 'Безличный, сухой, холодный', 'Large corporate customer service systems can feel frustratingly cold and impersonal.', 'Katta korporativ mijozlarga xizmat ko''rsatish tizimlari dilxira darajada sovuq va shaxsiyatsiz tuyulishi mumkin.', '["impersonal tone","impersonal service","impersonal atmosphere"]'::jsonb, '["aloof","distant","detached","emotionless"]'::jsonb, 257),
  ('Ornament', 13, 'noun', '/ˈɔː.nə.mənt/', 'A thing used to make something look more attractive but having no practical purpose, especially a small object such as a figurine.', 'Bezak, naqsh, zeb-ziynat', 'Украшение, орнамент', 'The Christmas tree was decorated with colorful glass baubles and sparkling silver ornaments.', 'Yangi yil archasi rang-barang shisha sharlar va yaltiroq kumush bezaklar bilan bezatilgan edi.', '["tree ornament","decorative ornament","carved ornament"]'::jsonb, '["decoration","adornment","trinket","embellishment"]'::jsonb, 258),
  ('Pedestrian', 13, 'noun', '/pəˈdes.tri.ən/', 'A person walking rather than traveling in a vehicle.', 'Piyoda, yo''lovchi', 'Пешеход; пешеходный', 'Drivers must yield the right of way to any pedestrian crossing at a marked zebra crossing.', 'Haydovchilar chizilgan piyodalar o''tish joyidan o''tayotgan har qanday piyodaga yo''l berishlari shart.', '["pedestrian crossing","pedestrian zone","pedestrian safety"]'::jsonb, '["walker","foot traveler","passerby"]'::jsonb, 259),
  ('Sanctuary', 13, 'noun', '/ˈsæŋk.tʃʊə.ri/', 'A place of safety, refuge, or nature reserve where birds and animals are protected.', 'Qo''riqxona, panohgoh, xavfsiz maskan', 'Убежище, заповедник, святилище', 'The national park acts as a protected wildlife sanctuary for endangered snow leopards.', 'Milliy bog'' yo''qolib ketish xavfi ostidagi qor qoplonlari uchun himoyalangan yovvoyi tabiat qo''riqxonasi bo''lib xizmat qiladi.', '["wildlife sanctuary","bird sanctuary","seek sanctuary"]'::jsonb, '["refuge","haven","reserve","shelter"]'::jsonb, 260),
  ('Spectator', 13, 'noun', '/spekˈteɪ.tər/', 'A person who watches at a show, game, or other sports event.', 'Tomoshabin, kuzatuvchi', 'Зритель, наблюдатель', 'Over fifty thousand passionate football spectators packed into the stadium for the cup final.', 'Kubok finali uchun stadionga ellik mingdan ortiq qizg''in futbol tomoshabinlari to''plandilar.', '["spectator sports","cheering spectators","spectator stands"]'::jsonb, '["watcher","viewer","onlooker","observer"]'::jsonb, 261),
  ('Asset', 14, 'noun', '/ˈæs.et/', 'A useful or valuable quality, person, or thing; or an item of property owned by a person or company.', 'Aktiv, qimmatli boylik, foydali jihat', 'Актив, ценное качество, имущество', 'Her fluency in four foreign languages made her an invaluable asset to the diplomatic team.', 'Uning to''rtta xorijiy tilni erkin bilishi uni diplomatik guruh uchun bebaho boylikka aylantirdi.', '["valuable asset","financial assets","liquid assets"]'::jsonb, '["advantage","benefit","resource","holding"]'::jsonb, 262),
  ('Aspect', 14, 'noun', '/ˈæs.pekt/', 'A particular part or feature of something.', 'Jihat, tomon, xususiyat', 'Аспект, сторона, точка зрения', 'Vocabulary range is a vital aspect of your evaluation in both IELTS Writing and Speaking.', 'Lug''at boyligi doirasi IELTS Writing va Speaking baholashining muhim jihati hisoblanadi.', '["every aspect","key aspect","aspect of life"]'::jsonb, '["feature","facet","dimension","side"]'::jsonb, 263),
  ('Braille', 14, 'noun', '/breɪl/', 'A form of written language for blind people, in which characters are represented by patterns of raised dots that are felt with the fingertips.', 'Brayl yozuvi (ko''zi ojizlar alifbosi)', 'Шрифт Брайля', 'Elevator control buttons in public buildings are labeled in raised Braille for accessibility.', 'Jamoat binolaridagi lift tugmalari qulaylik uchun bo''rtma Brayl yozuvi bilan belgilangan.', '["read Braille","Braille alphabet","Braille signs"]'::jsonb, '["raised dot script","tactile writing"]'::jsonb, 264),
  ('Bud', 14, 'noun', '/bʌd/', 'A compact knob-like growth on a plant that develops into a leaf, flower, or shoot.', 'G''uncha, kurtak', 'Почка (растения), бутон', 'In early April, rose buds begin to swell and open into vibrant crimson petals.', 'Aprel oyi boshlarida atirgul g''unchalari bo''rtib, yorqin to''q qizil barglarga ochila boshlaydi.', '["taste buds","nip in the bud","rose bud"]'::jsonb, '["sprout","flower shoot","blossom"]'::jsonb, 265),
  ('Coordinate', 14, 'verb', '/kəʊˈɔː.dɪ.neɪt/', 'To bring the different elements of a complex activity or organization into a harmonious or efficient relationship.', 'Muvofiqlashtirmoq, uyg''unlashtirmoq', 'Координировать, согласовывать', 'The event manager worked tirelessly to coordinate the sound, lighting, and stage arrangements.', 'Tadbir menejeri ovoz, yoritish va sahna sozlamalarini muvofiqlashtirish uchun tinimsiz ishladi.', '["coordinate efforts","coordinate activities","closely coordinate"]'::jsonb, '["organize","harmonize","synchronize","integrate"]'::jsonb, 266),
  ('Disprove', 14, 'verb', '/dɪsˈpruːv/', 'To prove that something is false or wrong.', 'Noto''g''riligini isbotlamoq, inkor qilmoq', 'Опровергать, доказывать ложность', 'Subsequent rigorous laboratory experiments disproved the earlier claims of cold fusion.', 'Keyingi sinchkov laboratoriya tajribalari sovuq yadro sintezi haqidagi oldingi da''volarning xatoligini isbotladi.', '["disprove a theory","disprove a myth","conclusively disprove"]'::jsonb, '["refute","debunk","invalidate","negate"]'::jsonb, 267),
  ('Humanitarian', 14, 'adjective', '/hjuːˌmæn.ɪˈteə.ri.ən/', 'Concerned with or seeking to promote human welfare and alleviate suffering.', 'Insonparvar, gumanitar', 'Гуманитарный, человеколюбивый', 'Red Crescent volunteers delivered vital humanitarian aid to earthquake-stricken villages.', 'Qizil Yarim Oy ko''ngillilari zilziladan jabr ko''rgan qishloqlarga hayotiy muhim insonparvarlik yordamini yetkazdilar.', '["humanitarian aid","humanitarian crisis","humanitarian mission"]'::jsonb, '["charitable","philanthropic","altruistic","compassionate"]'::jsonb, 268),
  ('Hypothesis', 14, 'noun', '/haɪˈpɒθ.ə.sɪs/', 'A proposed explanation made on the basis of limited evidence as a starting point for further investigation.', 'Faraziya, ilmiy taxmin, gipoteza', 'Гипотеза, догадка, предположение', 'Scientists tested their hypothesis about water presence on Mars using rover soil samples.', 'Olimlar Marsda suv borligi haqidagi o''z gipotezalarini marsoxod tuproq namunalari yordamida sinab ko''rdilar.', '["test a hypothesis","formulate a hypothesis","working hypothesis"]'::jsonb, '["theory","conjecture","premise","assumption"]'::jsonb, 269),
  ('Imprint', 14, 'noun', '/ˈɪm.prɪnt/', 'An impression or mark made by pressure on a surface; an indelible effect or impact.', 'Iz, tamg''a, qoldirilgan ta''sir', 'Отпечаток, след, оттиск', 'Fossils show the clear imprint of ancient fern leaves preserved in sedimentary rock.', 'Qazilma toshlar cho''kindi jinslarda saqlanib qolgan qadimiy qirqquloq barglarining yaqqol izini ko''rsatadi.', '["leave an imprint","carbon imprint","lasting imprint"]'::jsonb, '["mark","impression","stamp","trace"]'::jsonb, 270),
  ('Informative', 14, 'adjective', '/ɪnˈfɔː.mə.tɪv/', 'Providing useful or interesting information.', 'Mazmunli, ma''lumotga boy, foydali', 'Информативный, содержательный', 'The university seminar on IELTS preparation was exceptionally engaging and informative.', 'IELTS tayyorgarligi bo''yicha o''tkazilgan universitet seminari g''oyat qiziqarli va ma''lumotga boy bo''ldi.', '["informative speech","highly informative","informative brochure"]'::jsonb, '["illuminating","educational","instructive","enlightening"]'::jsonb, 271),
  ('Optic', 14, 'adjective', '/ˈɒp.tɪk/', 'Relating to the eye or the science of vision and light.', 'Optik, ko''rishga oid', 'Оптический, зрительный', 'The optic nerve transmits visual electrical signals directly from the retina to the brain.', 'Optik ko''rish nervi vizual elektr signallarini to''r pardadan to''g''ridan-to''g''ri miyaga uzatadi.', '["optic nerve","fiber optic","optic illusion"]'::jsonb, '["visual","ocular","optical","vision-related"]'::jsonb, 272),
  ('Premise', 14, 'noun', '/ˈprem.ɪs/', 'A previous statement or proposition from which another is inferred or follows as a conclusion.', 'Asos, boshlang''ich mulohaza, shart', 'Посылка (логическая), предпосылка', 'The philosophical argument was based on the false premise that all humans act purely rationally.', 'Falsafiy dalil barcha insonlar mutlaqo oqilona harakat qiladi degan soxta asosga qurilgan edi.', '["false premise","underlying premise","accept the premise"]'::jsonb, '["proposition","assumption","hypothesis","basis"]'::jsonb, 273),
  ('Rack', 14, 'noun', '/ræk/', 'A framework, typically with rails, bars, or hooks, for holding or storing things.', 'Polka, osqich, javon', 'Стеллаж, стойка, вешалка', 'The laboratory assistant arranged the glass test tubes neatly into the drying rack.', 'Laboratoriya xodimi shisha probirkani quritish javoniga tartibli qilib terib chiqdi.', '["luggage rack","spice rack","clothes rack"]'::jsonb, '["shelf","stand","frame","holder"]'::jsonb, 274),
  ('Renaissance', 14, 'noun', '/rəˈneɪ.səns/', 'A revival of or renewed interest in something, especially art, literature, or culture.', 'Uyg''onish davri, renessans, qayta yuksalish', 'Эпоха Возрождения, ренессанс', 'Central Asia experienced a splendid cultural and scientific Renaissance under the Timurid dynasty.', 'O''rta Osiyo Temuriylar sulolasi davrida muhtasham madaniy va ilmiy Uyg''onish davrini boshdan kechirdi.', '["Renaissance art","cultural renaissance","scientific renaissance"]'::jsonb, '["revival","rebirth","reawakening","resurgence"]'::jsonb, 275),
  ('Revere', 14, 'verb', '/rɪˈvɪər/', 'To feel deep respect or admiration for someone or something.', 'Ulug''lamoq, e''zozlamoq, bosh egmoq', 'Почитать, благоговеть', 'Citizens revere the memory of national heroes who sacrificed their lives for independence.', 'Fuqarolar mustaqillik uchun jonini fido qilgan milliy qahramonlar xotirasini e''zozlaydilar.', '["revere as a hero","widely revered","revere sacred traditions"]'::jsonb, '["respect","venerate","admire","honor"]'::jsonb, 276),
  ('Simultaneous', 14, 'adjective', '/ˌsɪm.əlˈteɪ.ni.əs/', 'Occurring, operating, or done at the very same time.', 'Bir vaqtning o''zida yuz beradigan, sinxron', 'Одновременный, синхронный', 'Professional interpreters provide simultaneous translation during international summit meetings.', 'Professional tarjimonlar xalqaro sammit yig''ilishlarida bir vaqtning o''zida sinxron tarjima qilib beradilar.', '["simultaneous translation","simultaneous broadcast","simultaneous equations"]'::jsonb, '["concurrent","synchronized","coincident","parallel"]'::jsonb, 277),
  ('Skeptic', 14, 'noun', '/ˈskep.tɪk/', 'A person inclined to question or doubt accepted opinions or claims.', 'Shubhalanuvchi, skeptik, ishonqiramaydigan', 'Скептик', 'Even the most cynical skeptics were persuaded by the overwhelming experimental data.', 'Hatto eng shubhachi skeptiklar ham inkor etib bo''lmas tajriba ma''lumotlariga qarab ishondilar.', '["born skeptic","convince skeptics","healthy skeptic"]'::jsonb, '["doubter","cynic","questioner","disbeliever"]'::jsonb, 278),
  ('Spatial', 14, 'adjective', '/ˈspeɪ.ʃəl/', 'Relating to space and the relationship of objects within it.', 'Fazoviy, makonga oid', 'Пространственный', 'Architects and civil engineers require exceptional spatial awareness to design 3D structures.', 'Me''morlar va muhandislar 3D inshootlarni loyihalash uchun ajoyib fazoviy tasavvurga ega bo''lishlari kerak.', '["spatial awareness","spatial distribution","spatial relationship"]'::jsonb, '["dimensional","structural","geographical","locational"]'::jsonb, 279),
  ('Specify', 14, 'verb', '/ˈspes.ɪ.faɪ/', 'To identify clearly and definitely; state a fact or requirement precisely.', 'Aniq ko''rsatmoq, belgilamoq', 'Уточнять, определять, оговаривать', 'Please clearly specify your dietary restrictions before booking the international airline meal.', 'Xalqaro samolyot taomini buyurtma qilishdan oldin o''z parhez cheklovlaringizni aniq ko''rsating.', '["specify requirements","clearly specify","specify a date"]'::jsonb, '["state","detail","designate","stipulate"]'::jsonb, 280),
  ('Wax', 14, 'noun', '/wæks/', 'A sticky, malleable organic substance produced by bees or synthesized from petroleum, used for candles and polish.', 'Mum (sham yoki asal mumi)', 'Воск', 'Honeybees secrete pure natural wax from their abdomen glands to construct honeycomb cells.', 'Asalarilar asalari uyasi kataklarini qurish uchun o''z bezlaridan tabiiy toza mumni ajratadilar.', '["candle wax","ear wax","wax polish"]'::jsonb, '["beeswax","paraffin","polish"]'::jsonb, 281),
  ('Accessory', 15, 'noun', '/əkˈses.ər.i/', 'A thing that can be added to something else in order to make it more useful, versatile, or attractive.', 'Aksessuar, qo''shimcha buyum', 'Аксессуар, принадлежность', 'A protective leather case is a sensible accessory to shield your new smartphone screen.', 'Charm g''ilof yangi smartfoningiz ekranini himoyalash uchun oqilona aksessuardir.', '["fashion accessory","car accessories","optional accessory"]'::jsonb, '["attachment","addition","supplement","extra"]'::jsonb, 282),
  ('Acquisition', 15, 'noun', '/ˌæk.wɪˈzɪʃ.ən/', 'An asset or object bought or obtained; also the learning or developing of a skill, habit, or quality.', 'Qo''lga kiritish, xarid, o''zlashtirish', 'Приобретение, овладение', 'Early childhood is the most fertile and rapid period for human language acquisition.', 'Erta bolalik insonning tilni o''zlashtirishi uchun eng unumdor va tezkor davrdir.', '["language acquisition","data acquisition","merger and acquisition"]'::jsonb, '["purchase","procurement","attainment","gain"]'::jsonb, 283),
  ('Adequate', 15, 'adjective', '/ˈæd.ə.kwət/', 'Satisfactory or acceptable in quality or quantity; sufficient.', 'Yetarli, qoniqarli, munosib', 'Адекватный, достаточный', 'Ensuring an adequate supply of fresh clean water is critical for public health in dry climates.', 'Toza ichimlik suvining yetarli ta''minotini kafolatlash quruq iqlimlarda aholi salomatligi uchun hal qiluvchidir.', '["adequate resources","adequate preparation","more than adequate"]'::jsonb, '["sufficient","enough","satisfactory","ample"]'::jsonb, 284),
  ('Cardboard', 15, 'noun', '/ˈkɑːd.bɔːd/', 'Pasteboard or stiff, thick paper, typically used for making boxes.', 'Karton, qalin qog''oz', 'Картон', 'Online purchases are securely packaged in sturdy recycled cardboard boxes.', 'Onlayn xaridlar mustahkam qayta ishlangan karton qutilarga xavfsiz qadoqlanadi.', '["cardboard box","corrugated cardboard","cardboard packaging"]'::jsonb, '["paperboard","pasteboard","stiff paper"]'::jsonb, 285),
  ('Dilemma', 15, 'noun', '/daɪˈlem.ə/', 'A situation in which a difficult choice has to be made between two or more alternatives, especially equally undesirable ones.', 'Dilemma, og''ir tanlov, mushkul ahvol', 'Дилемма, тяжелый выбор', 'She faced a painful moral dilemma: tell the truth and risk friendship, or stay silent.', 'U og''riqli axloqiy dilemma oldida qoldi: haqiqatni aytib do''stlikni xavf ostiga qo''yish yoki jim turish.', '["moral dilemma","face a dilemma","ethical dilemma"]'::jsonb, '["quandary","predicament","catch-22","impasse"]'::jsonb, 286),
  ('Elaborate', 15, 'adjective', '/ɪˈlæb.ər.ət/', 'Involving many carefully arranged parts or details; detailed and complicated in design.', 'Batafsil, mukammal ishlangan, murakkab', 'Сложный, тщательно разработанный', 'The architecture featured elaborate geometric mosaics characteristic of Islamic medieval art.', 'Me''morchilik islomiy o''rta asr san''atiga xos bo''lgan nozik va mukammal geometrik mozaikalarni namoyish etdi.', '["elaborate plan","elaborate design","elaborate on something"]'::jsonb, '["intricate","detailed","complex","ornate"]'::jsonb, 287),
  ('Facilitate', 15, 'verb', '/fəˈsɪl.ɪ.teɪt/', 'To make an action or process easy or easier.', 'Osonlashtirmoq, qulaylashtirmoq', 'Облегчать, способствовать', 'Modern educational technologies facilitate active collaborative learning between students.', 'Zamonaviy ta''lim texnologiyalari talabalar o''rtasidagi faol hamkorlikda o''rganishni osonlashtiradi.', '["facilitate learning","facilitate trade","facilitate discussion"]'::jsonb, '["ease","expedite","assist","aid"]'::jsonb, 288),
  ('Fleet', 15, 'noun', '/fliːt/', 'A group of ships sailing together; or a number of vehicles operating under one owner.', 'Flot, transportlar guruhi', 'Флот, парк (машин)', 'The logistics delivery company expanded its fleet with hundreds of zero-emission electric vans.', 'Logistika yetkazib berish kompaniyasi o''z avtoparkini yuzlab chiqindisiz elektr furgonlar bilan kengaytirdi.', '["naval fleet","fleet of cars","commercial fleet"]'::jsonb, '["naval force","armada","convoy","motor pool"]'::jsonb, 289),
  ('Grid', 15, 'noun', '/ɡrɪd/', 'A framework of spaced bars that are parallel to or cross each other; a network of electrical power lines.', 'Katakcha, to''r, elektr tarmog''i', 'Сетка, решетка, энергосистема', 'Extreme winter storms damaged transformers and knocked out the regional electrical grid.', 'Qahraton qish bo''ronlari transformatorlarni shikastlab, mintaqaviy elektr tarmog''ini ishdan chiqardi.', '["power grid","off the grid","grid structure"]'::jsonb, '["network","matrix","mesh","lattice"]'::jsonb, 290),
  ('Import', 15, 'verb', '/ɪmˈpɔːt/', 'To bring goods or services into a country from abroad for sale.', 'Import qilmoq, chetdan olib kirmoq', 'Импортировать, ввозить', 'Uzbekistan continues to import high-tech industrial machinery from Germany and Japan.', 'O''zbekiston Germaniya va Yaponiyadan yuqori texnologiyali sanoat uskunalarini import qilishda davom etmoqda.', '["import goods","import duties","import raw materials"]'::jsonb, '["bring in","ship in","procure abroad"]'::jsonb, 291),
  ('Infer', 15, 'verb', '/ɪnˈfɜːr/', 'To deduce or conclude information from evidence and reasoning rather than explicit statements.', 'Xulosa chiqarmoq, fahmlamoq', 'Делать вывод, заключать', 'In the IELTS Reading test, students must frequently infer the author''s implied attitude from the text.', 'IELTS Reading testida talabalar matndan muallifning yashirin munosabatini tez-tez fahmlab xulosa chiqarishlari kerak.', '["infer from","reasonably infer","infer meaning"]'::jsonb, '["deduce","conclude","gather","extrapolate"]'::jsonb, 292),
  ('Inflate', 15, 'verb', '/ɪnˈfleɪt/', 'To fill a balloon, tire, or other expandable object with air or gas; to increase prices artificially.', 'Damlamaq, shishirmoq; narxni oshirmoq', 'Надувать, раздувать; взвинчивать цены', 'Make sure you inflate your bicycle tires to the recommended pressure before a long journey.', 'Uzoq safarga chiqishdan oldin velosiped shinalarini tavsiya etilgan bosimda damlaganingizga ishonch hosil qiling.', '["inflate tires","inflate prices","inflate expectations"]'::jsonb, '["blow up","pump up","swell","expand"]'::jsonb, 293),
  ('Innate', 15, 'adjective', '/ɪˈneɪt/', 'Inborn; natural; existing in someone from birth rather than learned.', 'Tug''ma, fitriy, tabiatdan berilgan', 'Врожденный, природный', 'Young children seem to possess an innate curiosity to explore and understand the world.', 'Kichik bolalar dunyoni tadqiq qilish va tushunish bo''yicha tug''ma qiziquvchanlikka ega bo''ladilar.', '["innate ability","innate talent","innate desire"]'::jsonb, '["inborn","natural","instinctive","intrinsic"]'::jsonb, 294),
  ('Marble', 15, 'noun', '/ˈmɑː.bəl/', 'A hard crystalline metamorphic form of limestone, typically white with coloured streaks, used in sculpture and architecture.', 'Marmar', 'Мрамор', 'The palace ballroom floor was laid with polished white Italian Carrara marble.', 'Qasrning bal zali poliga silliqlangan oq rangli Italiya Karrara marmari yotqizilgan edi.', '["marble statue","marble floor","carve in marble"]'::jsonb, '["limestone rock","sculpture stone"]'::jsonb, 295),
  ('Mast', 15, 'noun', '/mɑːst/', 'A tall upright post, spar, or other structure on a ship or boat, in sailing vessels carrying a sail or sails.', 'Machta, kema ustuni', 'Мачта', 'The captain ordered the crew to climb the main mast and unfurl the giant canvas sails.', 'Kapitan jamoaga asosiy machtaga chiqib, bahaybat brezent yelkanlarni yoyishni buyurdi.', '["ship''s mast","main mast","tall mast"]'::jsonb, '["spar","pole","upright","pylon"]'::jsonb, 296),
  ('Nausea', 15, 'noun', '/ˈnɔː.zi.ə/', 'A feeling of sickness with an inclination to vomit.', 'Ko''ngil aynishi, behuzurlik', 'Тошнота, морская болезнь', 'Turbulence on the small airplane caused acute motion sickness and nausea among several passengers.', 'Kichik samolyotdagi turbulentlik bir nechta yo''lovchilarda kuchli chayqalish va ko''ngil aynishiga sabab bo''ldi.', '["feel nausea","suffer from nausea","waves of nausea"]'::jsonb, '["queasiness","sickness","biliousness","motion sickness"]'::jsonb, 297),
  ('Naval', 15, 'adjective', '/ˈneɪ.vəl/', 'Relating to a country''s navy, warships, or maritime combat forces.', 'Harbiy-dengizga oid, harbiy flotga oid', 'Военно-морской, морской', 'The historic naval battle off the coast of Trafalgar cemented British maritime supremacy.', 'Trafalgar qirg''og''i yaqinidagi tarixiy harbiy dengiz jangi Britaniyaning dengizdagi hukmronligini mustahkamladi.', '["naval base","naval forces","naval officer"]'::jsonb, '["maritime","nautical","marine","sea-fighting"]'::jsonb, 298),
  ('Pouch', 15, 'noun', '/paʊtʃ/', 'A small flexible bag, typically carried on a person; or a pocket of skin in which animals carry their young.', 'Xaltacha, hamyon; jonivor qorin xaltasi', 'Мешочек, сумка (у кенгуру)', 'A mother kangaroo protects and nurses her newborn joey inside her warm abdominal pouch.', 'Ona kenguru o''zining yangi tug''ilgan bolasini iliq qorin xaltachasi ichida himoya qiladi va emizadi.', '["kangaroo pouch","leather pouch","tobacco pouch"]'::jsonb, '["pocket","sac","bag","purse"]'::jsonb, 299),
  ('Saturated', 15, 'adjective', '/ˈsætʃ.ər.eɪ.tɪd/', 'Holding as much water or moisture as can be absorbed; thoroughly soaked.', 'Suvga to''yingan, shilta bo''lgan', 'Насыщенный, промокший насквозь', 'After walking through the heavy storm without an umbrella, his clothes were completely saturated.', 'Zontiksiz kuchli bo''ron ostida yurgach, uning kiyimlari shilta bo''lib suvga to''yib ketgan edi.', '["saturated fat","saturated with water","saturated market"]'::jsonb, '["soaked","drenched","steeped","waterlogged"]'::jsonb, 300),
  ('Updated', 15, 'adjective', '/ʌpˈdeɪ.tɪd/', 'Incorporating the most recent facts, changes, and modern features.', 'Yangilangan, zamonaviylashtirilgan', 'Обновленный, актуализированный', 'The website includes an updated curriculum with full audio phonetics and verified Uzbek explanations.', 'Veb-sayt to''liq audio talaffuz va tekshirilgan o''zbekcha izohlarga ega yangilangan o''quv dasturini o''z ichiga oladi.', '["updated version","updated edition","updated curriculum"]'::jsonb, '["modernized","revised","refreshed","current"]'::jsonb, 301)
) AS w(word, unit_number, part_of_speech, ipa_us, definition_en, translation_uz, translation_ru, example_sentence_en, example_translation_uz, collocations, synonyms, display_order)
JOIN vocabulary_units u ON u.unit_number = w.unit_number
ON CONFLICT (normalized_word) DO UPDATE SET
  definition_en = EXCLUDED.definition_en,
  translation_uz = EXCLUDED.translation_uz,
  example_sentence_en = EXCLUDED.example_sentence_en,
  example_translation_uz = EXCLUDED.example_translation_uz,
  collocations = EXCLUDED.collocations,
  synonyms = EXCLUDED.synonyms;
